// Vòng 3 — Giải nghĩa, phần bổ sung. Ba gợi ý mở dần: lời giải nghĩa → gợi ý thêm → tiếng đầu (hoặc tiếng cuối).
// `acc` là những cách gõ khác cũng được chấp nhận. Đáp án không được trùng đáp án vòng Ghép từ.
import type { Clue } from "./vua-tieng-viet.ts";

const EASY: Clue[] = [
  { id: "R2-101", lv: 1, tp: "vocab", h: ["Nơi gửi thư, gửi bưu phẩm và nhận bưu kiện.", "Danh từ hai tiếng, thường có hòm thư màu vàng phía trước.", "Tiếng đầu là “bưu”."], a: "bưu điện", why: "Bưu điện là nơi chuyển thư từ, bưu phẩm." },
  { id: "R2-102", lv: 1, tp: "vocab", h: ["Nơi khám và chữa bệnh, có bác sĩ, y tá làm việc.", "Danh từ hai tiếng, xe cứu thương hay chạy về đây.", "Tiếng đầu là “bệnh”."], a: "bệnh viện", acc: ["nhà thương"], why: "Bệnh viện là nơi khám, chữa bệnh và chăm sóc người ốm." },
  { id: "R2-103", lv: 1, tp: "vocab", h: ["Nơi máy bay cất cánh và hạ cánh.", "Hành khách làm thủ tục ở nhà ga ở đây.", "Tiếng đầu là “sân”."], a: "sân bay", acc: ["phi trường"], why: "Sân bay (phi trường) là nơi máy bay lên xuống." },
  { id: "R2-104", lv: 1, tp: "vocab", h: ["Cửa hàng lớn bán đủ thứ hàng, khách tự chọn rồi ra quầy trả tiền.", "Danh từ hai tiếng, thường có xe đẩy.", "Tiếng đầu là “siêu”."], a: "siêu thị", why: "Siêu thị bày bán nhiều mặt hàng để khách tự chọn." },
  { id: "R2-105", lv: 1, tp: "vocab", h: ["Khu đất rộng có cây xanh, ghế đá, lối đi cho mọi người dạo chơi.", "Danh từ hai tiếng, buổi sáng nhiều người tập thể dục ở đây.", "Tiếng đầu là “công”."], a: "công viên", why: "Công viên là vườn hoa, cây cảnh công cộng." },
  { id: "R2-106", lv: 1, tp: "vocab", h: ["Nơi nuôi nhiều loài thú để mọi người đến xem.", "Có hổ, voi, hươu cao cổ trong chuồng.", "Tiếng đầu là “vườn”."], a: "vườn thú", acc: ["sở thú", "thảo cầm viên", "vườn bách thú"], why: "Vườn thú (sở thú) nuôi và trưng bày động vật." },
  { id: "R2-107", lv: 1, tp: "vocab", h: ["Người chăm sóc bệnh nhân, tiêm thuốc, giúp việc cho bác sĩ.", "Danh từ hai tiếng, nghề trong bệnh viện.", "Tiếng đầu là “y”."], a: "y tá", acc: ["điều dưỡng"], why: "Y tá (điều dưỡng) chăm sóc người bệnh theo chỉ định của bác sĩ." },
  { id: "R2-108", lv: 1, tp: "vocab", h: ["Người nấu ăn chuyên nghiệp trong nhà hàng.", "Thường đội chiếc mũ trắng cao.", "Tiếng đầu là “đầu”."], a: "đầu bếp", why: "Đầu bếp là người nấu ăn chính trong bếp." },
  { id: "R2-109", lv: 1, tp: "vocab", h: ["Người giữ gìn trật tự, an toàn xã hội và điều khiển giao thông.", "Danh từ hai tiếng, gốc Hán Việt.", "Tiếng đầu là “cảnh”."], a: "cảnh sát", acc: ["công an"], why: "Cảnh sát (công an) giữ gìn an ninh, trật tự." },
  { id: "R2-110", lv: 1, tp: "vocab", h: ["Đồ dùng có lông nhỏ, dùng với kem để làm sạch răng.", "Mỗi sáng và tối em đều dùng.", "Tiếng đầu là “bàn”."], a: "bàn chải", acc: ["bàn chải đánh răng"], why: "Bàn chải đánh răng giúp làm sạch răng miệng." },
  { id: "R2-111", lv: 1, tp: "vocab", h: ["Chất tạo bọt, dùng để rửa tay, tắm giặt cho sạch.", "Miền Nam thường gọi là “xà bông”.", "Tiếng đầu là “xà”."], a: "xà phòng", acc: ["xà bông"], why: "Xà phòng giúp tẩy sạch bụi bẩn và vi khuẩn." },
  { id: "R2-112", lv: 1, tp: "vocab", h: ["Đồ điện dùng để giữ thức ăn luôn lạnh, tươi lâu.", "Có ngăn đá để làm kem, làm đá.", "Tiếng đầu là “tủ”."], a: "tủ lạnh", why: "Tủ lạnh bảo quản thức ăn ở nhiệt độ thấp." },
  { id: "R2-113", lv: 1, tp: "vocab", h: ["Máy dùng để giặt quần áo tự động.", "Có loại cửa trên, có loại cửa trước.", "Tiếng cuối là “giặt”."], a: "máy giặt", why: "Máy giặt giúp giặt giũ đỡ vất vả." },
  { id: "R2-114", lv: 1, tp: "vocab", h: ["Máy làm mát hoặc sưởi ấm cả căn phòng, thường treo trên tường.", "Có điều khiển từ xa để chỉnh nhiệt độ.", "Tiếng đầu là “điều”."], a: "điều hoà", acc: ["máy lạnh", "máy điều hoà"], why: "Điều hoà (máy lạnh) giữ nhiệt độ phòng dễ chịu." },
  { id: "R2-115", lv: 1, tp: "vocab", h: ["Thiết bị dùng để gọi và nghe người ở xa nói chuyện.", "Ngày nay nhiều người mang theo trong túi.", "Tiếng đầu là “điện”."], a: "điện thoại", why: "Điện thoại truyền tiếng nói đi xa." },
  { id: "R2-116", lv: 1, tp: "vocab", h: ["Chiếc mũ cứng phải đội khi đi xe máy, xe đạp điện.", "Giúp bảo vệ đầu khi chẳng may ngã.", "Tiếng đầu là “mũ”."], a: "mũ bảo hiểm", acc: ["nón bảo hiểm"], why: "Mũ bảo hiểm bảo vệ đầu người tham gia giao thông." },
  { id: "R2-117", lv: 1, tp: "vocab", h: ["Đồ dùng để che mưa, che nắng, có cán cầm và có thể gấp lại.", "Miền Nam còn gọi là cây dù.", "Tiếng đầu là “cái”."], a: "cái ô", acc: ["ô", "dù", "cái dù", "chiếc ô"], why: "Cái ô (dù) che mưa, che nắng." },
  { id: "R2-118", lv: 1, tp: "vocab", h: ["Hộp nhỏ để đựng bút, thước, tẩy của học sinh.", "Danh từ hai tiếng.", "Tiếng đầu là “hộp”."], a: "hộp bút", acc: ["hộp đựng bút", "bao bút"], why: "Hộp bút giữ đồ dùng học tập gọn gàng." },
  { id: "R2-119", lv: 1, tp: "vocab", h: ["Loài thú nhỏ có bộ lông gai nhọn, cuộn tròn lại khi gặp nguy hiểm.", "Danh từ chỉ con vật.", "Tiếng đầu là “con”."], a: "con nhím", acc: ["nhím"], why: "Nhím xù lông gai để tự vệ." },
  { id: "R2-120", lv: 1, tp: "vocab", h: ["Con vật có mai cứng, bò rất chậm, sống cả trên cạn lẫn dưới nước.", "Thi chạy với thỏ trong truyện ngụ ngôn.", "Tiếng đầu là “con”."], a: "con rùa", acc: ["rùa"], why: "Rùa có mai cứng che chở thân mình." },
  { id: "R2-121", lv: 1, tp: "vocab", h: ["Con vật nhỏ, đuôi xù, leo trèo giỏi, thích ăn hạt dẻ.", "Danh từ chỉ con vật.", "Tiếng đầu là “con”."], a: "con sóc", acc: ["sóc"], why: "Sóc sống trên cây, ăn quả và hạt." },
  { id: "R2-122", lv: 1, tp: "vocab", h: ["Côn trùng làm ra mật ngọt, sống thành đàn trong tổ.", "Bị nó đốt thì sưng và đau.", "Tiếng đầu là “con”."], a: "con ong", acc: ["ong", "ong mật"], why: "Ong hút mật hoa để làm mật." },
  { id: "R2-123", lv: 1, tp: "vocab", h: ["Côn trùng nhỏ phát sáng lập loè vào ban đêm.", "Danh từ hai tiếng, là từ láy.", "Tiếng đầu là “đom”."], a: "đom đóm", why: "Đom đóm có bộ phận phát sáng ở bụng." },
  { id: "R2-124", lv: 1, tp: "vocab", h: ["Con vật sống dưới biển, có tám xúc tu, phun mực khi gặp nguy.", "Danh từ hai tiếng.", "Tiếng đầu là “bạch”."], a: "bạch tuộc", why: "Bạch tuộc có tám tay với giác bám." },
  { id: "R2-125", lv: 1, tp: "vocab", h: ["Loài chim săn mồi ban đêm, mắt to tròn, đầu xoay được rất xa.", "Có tên gọi gắn với một con vật nuôi trong nhà.", "Tiếng đầu là “cú”."], a: "cú mèo", acc: ["chim cú", "cú"], why: "Cú mèo săn chuột vào ban đêm." },
  { id: "R2-126", lv: 1, tp: "vocab", h: ["Con vật có vòi dài, tai to như cái quạt, rất khoẻ.", "Ở Tây Nguyên, nó được dùng để chở gỗ.", "Tiếng đầu là “con”."], a: "con voi", acc: ["voi"], why: "Voi là loài thú lớn nhất trên cạn." },
  { id: "R2-127", lv: 1, tp: "vocab", h: ["Dòng nước đổ từ trên cao xuống.", "Bản Giốc là một ví dụ nổi tiếng.", "Tiếng cuối là “nước”."], a: "thác nước", acc: ["thác"], why: "Thác nước hình thành ở nơi lòng sông dốc đứng." },
  { id: "R2-128", lv: 1, tp: "vocab", h: ["Khoảng rỗng lớn trong lòng núi đá.", "Phong Nha – Kẻ Bàng có rất nhiều.", "Tiếng đầu là “hang”."], a: "hang động", acc: ["hang", "động"], why: "Hang động thường do nước bào mòn đá vôi mà thành." },
  { id: "R2-129", lv: 1, tp: "vocab", h: ["Vùng đất được bao quanh bởi nước.", "Phú Quốc, Côn Đảo đều là loại này.", "Tiếng đầu là “hòn”."], a: "hòn đảo", acc: ["đảo"], why: "Đảo là phần đất nổi giữa biển, sông, hồ." },
  { id: "R2-130", lv: 1, tp: "vocab", h: ["Dải cát ven biển, nơi người ta tắm biển, nghỉ mát.", "Mùa hè đông nghịt người.", "Tiếng đầu là “bãi”."], a: "bãi biển", why: "Bãi biển là dải đất ven bờ biển." },
  { id: "R2-131", lv: 1, tp: "vocab", h: ["Vệt sáng vụt qua bầu trời đêm, người ta hay ước khi thấy nó.", "Danh từ hai tiếng.", "Tiếng đầu là “sao”."], a: "sao băng", why: "Sao băng là thiên thạch cháy sáng khi lao vào bầu khí quyển." },
  { id: "R2-132", lv: 1, tp: "vocab", h: ["Mưa có những hạt nước đóng băng rơi xuống.", "Có thể làm vỡ ngói, hỏng hoa màu.", "Tiếng đầu là “mưa”."], a: "mưa đá", why: "Mưa đá xảy ra khi giọt nước bị đông cứng trong đám mây." },
  { id: "R2-133", lv: 1, tp: "vocab", h: ["Bánh làm từ bột gạo nếp, viên tròn có nhân đường, ăn vào Tết Hàn thực.", "Hồ Xuân Hương có bài thơ cùng tên.", "Tiếng đầu là “bánh”."], a: "bánh trôi", why: "Bánh trôi được thả vào nồi nước sôi, chín thì nổi lên." },
  { id: "R2-134", lv: 1, tp: "vocab", h: ["Bánh hình trụ dài gói lá chuối, món Tết quen thuộc ở miền Nam.", "Anh em với bánh chưng.", "Tiếng đầu là “bánh”."], a: "bánh tét", why: "Bánh tét là bánh Tết truyền thống của Nam Bộ." },
  { id: "R2-135", lv: 1, tp: "vocab", h: ["Món ăn nước nổi tiếng: sợi bánh gạo trắng mềm, nước dùng ninh xương, thịt bò hoặc gà.", "Món ăn nổi tiếng của Hà Nội và Nam Định.", "Có một tiếng, bắt đầu bằng “ph”."], a: "phở", acc: ["phở bò", "phở gà"], why: "Phở là món ăn tiêu biểu của ẩm thực Việt Nam." },
  { id: "R2-136", lv: 1, tp: "vocab", h: ["Bộ phận co bóp liên tục để bơm máu đi khắp cơ thể.", "Nằm trong lồng ngực, hơi lệch về bên trái.", "Tiếng đầu là “trái”."], a: "trái tim", acc: ["tim", "quả tim"], why: "Tim là bộ phận bơm máu nuôi cơ thể." },
  { id: "R2-137", lv: 1, tp: "vocab", h: ["Bộ phận giúp cơ thể hít khí vào và thở khí ra.", "Người có hai bộ phận này trong lồng ngực.", "Tiếng đầu là “lá”."], a: "lá phổi", acc: ["phổi"], why: "Phổi trao đổi khí, đưa ô xi vào máu." },
  { id: "R2-138", lv: 1, tp: "vocab", h: ["Bộ phận như chiếc túi chứa và nghiền nhỏ thức ăn.", "Miền Nam còn gọi là “bao tử”.", "Tiếng đầu là “dạ”."], a: "dạ dày", acc: ["bao tử"], why: "Dạ dày co bóp và tiết dịch để tiêu hoá thức ăn." },
  { id: "R2-139", lv: 1, tp: "vocab", h: ["Hàng lông mọc phía trên mắt.", "Danh từ hai tiếng.", "Tiếng đầu là “lông”."], a: "lông mày", why: "Lông mày giúp ngăn mồ hôi chảy vào mắt." },
  { id: "R2-140", lv: 1, tp: "vocab", h: ["Thời khắc chuyển từ năm cũ sang năm mới.", "Đêm ba mươi Tết, nhiều nơi bắn pháo hoa.", "Tiếng đầu là “giao”."], a: "giao thừa", why: "Giao thừa là lúc năm cũ qua, năm mới đến." },
  { id: "R2-141", lv: 1, tp: "vocab", h: ["Năm dương lịch có 366 ngày, tháng hai có 29 ngày.", "Cứ bốn năm thường có một lần.", "Tiếng đầu là “năm”."], a: "năm nhuận", why: "Năm nhuận có thêm ngày 29 tháng 2." },
  { id: "R2-142", lv: 1, tp: "vocab", h: ["Khoảng thời gian bảy ngày, từ thứ hai đến chủ nhật.", "Danh từ hai tiếng.", "Tiếng đầu là “tuần”."], a: "tuần lễ", acc: ["tuần"], why: "Một tuần lễ có bảy ngày." },
  { id: "R2-143", lv: 1, tp: "vocab", h: ["Đồ chơi gồm nhiều mảnh nhỏ, ghép lại thành một bức tranh.", "Danh từ ba tiếng.", "Tiếng đầu là “tranh”."], a: "tranh ghép", acc: ["xếp hình", "ghép hình"], why: "Tranh ghép rèn tính kiên nhẫn và óc quan sát." },
  { id: "R2-144", lv: 1, tp: "vocab", h: ["Trò chơi dân gian: một người bịt mắt đi bắt những người khác.", "Danh từ ba tiếng.", "Tiếng đầu là “bịt”."], a: "bịt mắt bắt dê", why: "Người bịt mắt vừa đi vừa đoán chỗ “dê” để bắt." },
  { id: "R2-145", lv: 1, tp: "vocab", h: ["Đồ chơi bằng gỗ hình nón, có đầu nhọn, quay tít trên mặt đất.", "Trẻ em quấn dây rồi giật mạnh cho nó quay.", "Tiếng đầu là “con”."], a: "con quay", acc: ["con cù"], why: "Con quay (con cù) là đồ chơi dân gian quen thuộc." },
  { id: "R2-146", lv: 1, tp: "vocab", h: ["Người lái tàu, thuyền lớn và chỉ huy cả con tàu.", "Danh từ hai tiếng, gốc Hán Việt.", "Tiếng đầu là “thuyền”."], a: "thuyền trưởng", why: "Thuyền trưởng chịu trách nhiệm cao nhất trên con tàu." },
  { id: "R2-147", lv: 1, tp: "vocab", h: ["Người du hành bay vào vũ trụ.", "Phạm Tuân là người Việt Nam đầu tiên làm việc này.", "Tiếng đầu là “nhà”."], a: "nhà du hành vũ trụ", acc: ["phi hành gia", "nhà du hành"], why: "Năm 1980, Phạm Tuân bay vào vũ trụ trên tàu Soyuz 37." },
  { id: "R2-148", lv: 1, tp: "vocab", h: ["Người làm việc chữa cháy, cứu người trong đám cháy.", "Gọi số 114 khi cần.", "Tiếng đầu là “lính”."], a: "lính cứu hoả", acc: ["lính cứu hỏa", "cứu hoả", "cảnh sát phòng cháy chữa cháy"], why: "Lính cứu hoả dập lửa và cứu nạn." },
  { id: "R2-149", lv: 1, tp: "vocab", h: ["Ngày đầu tiên của năm âm lịch, cả nhà sum họp, chúc Tết nhau.", "Gồm ba tiếng.", "Tiếng đầu là “Tết”."], a: "Tết Nguyên Đán", acc: ["Tết", "Tết ta", "Tết cổ truyền"], why: "“Nguyên” là bắt đầu, “đán” là buổi sớm: buổi sáng đầu năm." },
  { id: "R2-150", lv: 1, tp: "vocab", h: ["Ngày mùng năm tháng năm âm lịch, có tục ăn rượu nếp, hoa quả để “giết sâu bọ”.", "Danh từ ba tiếng.", "Tiếng đầu là “Tết”."], a: "Tết Đoan Ngọ", acc: ["Đoan Ngọ", "Tết diệt sâu bọ"], why: "Tết Đoan Ngọ còn gọi là Tết diệt sâu bọ." },
  { id: "R2-151", lv: 1, tp: "vocab", h: ["Con vật có tám chân, chăng tơ thành lưới để bắt côn trùng.", "Danh từ chỉ con vật.", "Tiếng đầu là “con”."], a: "con nhện", acc: ["nhện"], why: "Nhện giăng tơ để bẫy mồi." },
  { id: "R2-152", lv: 1, tp: "vocab", h: ["Loài cá lớn nhất, sống ở biển, thở bằng phổi và phun nước lên cao.", "Danh từ hai tiếng.", "Tiếng đầu là “cá”."], a: "cá voi", why: "Cá voi là loài thú có vú sống dưới biển." },
  { id: "R2-153", lv: 1, tp: "vocab", h: ["Côn trùng có đôi cánh nhiều màu sắc, hay đậu trên hoa.", "Lúc nhỏ nó là con sâu.", "Tiếng cuối là “bướm”."], a: "con bướm", acc: ["bướm", "bươm bướm"], why: "Bướm hút mật hoa và giúp hoa thụ phấn." },
  { id: "R2-154", lv: 1, tp: "vocab", h: ["Con vật sống ở ruộng, kêu “ộp ộp”, nhảy rất xa.", "Họ hàng với ếch nhưng thân nhỏ hơn.", "Tiếng đầu là “con”."], a: "con nhái", acc: ["nhái"], why: "Nhái là loài lưỡng cư nhỏ, sống ở ruộng, ao." },
  { id: "R2-155", lv: 1, tp: "vocab", h: ["Bông hoa có màu vàng, luôn quay về phía mặt trời.", "Hạt của nó rang lên ăn rất bùi.", "Tiếng đầu là “hoa”."], a: "hoa hướng dương", why: "Hoa hướng dương nghiêng theo hướng mặt trời." },
  { id: "R2-156", lv: 1, tp: "vocab", h: ["Loài hoa đỏ rực nở vào mùa hè, gắn với kỷ niệm học trò.", "Còn gọi là “hoa học trò”.", "Tiếng đầu là “hoa”."], a: "hoa phượng", acc: ["phượng", "hoa phượng vĩ"], why: "Hoa phượng nở báo hiệu mùa thi, mùa chia tay." },
  { id: "R2-157", lv: 1, tp: "vocab", h: ["Loại quả có gai nhọn bên ngoài, múi vàng, mùi rất nồng.", "Được gọi là “vua của các loại trái cây”.", "Tiếng đầu là “sầu”."], a: "sầu riêng", why: "Sầu riêng là đặc sản Nam Bộ." },
  { id: "R2-158", lv: 1, tp: "vocab", h: ["Quả hình tròn, vỏ xanh, cùi trắng, bên trong có nước ngọt mát.", "Bến Tre nổi tiếng có nhiều cây này.", "Tiếng đầu là “quả”."], a: "quả dừa", acc: ["dừa", "trái dừa"], why: "Nước dừa là thức uống giải khát quen thuộc." },
  { id: "R2-159", lv: 1, tp: "vocab", h: ["Quả có vỏ đỏ, ruột nhiều hạt li ti như vừng, mọc trên cây xương rồng.", "Danh từ ba tiếng.", "Tiếng đầu là “thanh”."], a: "thanh long", acc: ["quả thanh long", "trái thanh long"], why: "Thanh long là đặc sản Bình Thuận." },
  { id: "R2-160", lv: 1, tp: "vocab", h: ["Phương tiện đi trên đường ray, kéo nhiều toa chở khách.", "Chạy bằng đầu máy, có còi rất to.", "Tiếng đầu là “tàu”."], a: "tàu hỏa", acc: ["xe lửa", "tàu lửa"], why: "Tàu hoả (xe lửa) chạy trên đường sắt." },
  { id: "R2-161", lv: 1, tp: "vocab", h: ["Xe chở người bệnh cấp cứu đến bệnh viện, có còi hú.", "Danh từ ba tiếng.", "Tiếng đầu là “xe”."], a: "xe cứu thương", acc: ["xe cấp cứu"], why: "Xe cứu thương được ưu tiên đi trước trên đường." },
  { id: "R2-162", lv: 1, tp: "vocab", h: ["Đèn tín hiệu ba màu đặt ở ngã tư để điều khiển xe cộ.", "Đỏ dừng, xanh đi, vàng đi chậm.", "Tiếng đầu là “đèn”."], a: "đèn giao thông", acc: ["đèn tín hiệu", "đèn xanh đèn đỏ"], why: "Đèn giao thông giúp đường phố trật tự, an toàn." },
  { id: "R2-163", lv: 1, tp: "vocab", h: ["Lối đi dành cho người đi bộ qua đường, kẻ vạch trắng.", "Người ta còn ví nó như bộ lông ngựa vằn.", "Tiếng đầu là “vạch”."], a: "vạch kẻ đường", acc: ["vạch qua đường", "vạch sang đường", "vạch ngựa vằn"], why: "Người đi bộ nên qua đường ở chỗ có vạch kẻ." },
  { id: "R2-164", lv: 1, tp: "vocab", h: ["Dụng cụ để đo nhiệt độ cơ thể khi bị sốt.", "Danh từ hai tiếng, gốc Hán Việt.", "Tiếng đầu là “nhiệt”."], a: "nhiệt kế", acc: ["cặp nhiệt độ", "cái cặp nhiệt"], why: "Nhiệt kế đo nhiệt độ; người khoẻ khoảng 37 độ C." },
  { id: "R2-165", lv: 1, tp: "vocab", h: ["Đồ dùng có mặt phẳng nhẵn, soi vào thấy hình mình.", "Danh từ một hoặc hai tiếng.", "Tiếng đầu là “cái”."], a: "cái gương", acc: ["gương", "tấm gương", "gương soi"], why: "Gương phản chiếu hình ảnh." },
  { id: "R2-166", lv: 1, tp: "vocab", h: ["Bàn có các phím chữ, phím số để gõ vào máy tính.", "Danh từ hai tiếng.", "Tiếng đầu là “bàn”."], a: "bàn phím", why: "Bàn phím là thiết bị nhập liệu của máy tính." },
  { id: "R2-167", lv: 1, tp: "vocab", h: ["Bộ phận nhỏ cầm tay để di con trỏ trên màn hình máy tính.", "Có tên trùng với một con vật nhỏ hay gặm đồ.", "Tiếng đầu là “con”."], a: "con chuột", acc: ["chuột", "chuột máy tính"], why: "Chuột máy tính có tên vì hình dáng giống con chuột." },
  { id: "R2-168", lv: 1, tp: "vocab", h: ["Đồ dùng hình chữ nhật có ruột bông, để kê đầu khi ngủ.", "Danh từ một hoặc hai tiếng.", "Tiếng đầu là “cái”."], a: "cái gối", acc: ["gối", "chiếc gối"], why: "Gối giúp nằm ngủ êm và đúng tư thế." },
  { id: "R2-169", lv: 1, tp: "vocab", h: ["Tấm lưới bao quanh giường để ngăn muỗi đốt khi ngủ.", "Danh từ một hoặc hai tiếng.", "Tiếng đầu là “cái”."], a: "cái màn", acc: ["màn", "mùng", "cái mùng"], why: "Màn (mùng) ngăn muỗi truyền bệnh." },
  { id: "R2-170", lv: 1, tp: "vocab", h: ["Ngày cuối cùng của năm học, có lễ tổng kết, phát phần thưởng.", "Ngày này mở đầu cho kỳ nghỉ hè.", "Tiếng đầu là “bế”."], a: "bế giảng", acc: ["lễ bế giảng"], why: "“Bế” là đóng lại: lễ kết thúc năm học." },
  { id: "R2-171", lv: 1, tp: "vocab", h: ["Ngày đầu tiên của năm học mới, có đánh trống và chào cờ.", "Ở Việt Nam thường vào ngày 5 tháng 9.", "Tiếng đầu là “khai”."], a: "khai giảng", acc: ["lễ khai giảng", "khai trường"], why: "“Khai” là mở: ngày mở đầu năm học." },
  { id: "R2-172", lv: 1, tp: "vocab", h: ["Người đứng đầu, quản lý một trường học.", "Danh từ hai tiếng.", "Tiếng đầu là “hiệu”."], a: "hiệu trưởng", why: "Hiệu trưởng điều hành mọi hoạt động của nhà trường." },
  { id: "R2-173", lv: 1, tp: "vocab", h: ["Học sinh được bầu ra để quản lý, nhắc nhở cả lớp.", "Danh từ hai tiếng.", "Tiếng cuối là “trưởng”."], a: "lớp trưởng", why: "Lớp trưởng thay mặt lớp làm việc với thầy cô." },
  { id: "R2-174", lv: 1, tp: "vocab", h: ["Bảng ghi điểm, nhận xét kết quả học tập của học sinh.", "Cuối học kỳ bố mẹ hay xem.", "Tiếng đầu là “học”."], a: "học bạ", acc: ["sổ học bạ"], why: "Học bạ lưu kết quả học tập qua các năm." },
  { id: "R2-175", lv: 1, tp: "vocab", h: ["Tờ giấy ghi các môn học theo từng ngày, từng tiết trong tuần.", "Danh từ ba tiếng.", "Tiếng đầu là “thời”."], a: "thời khoá biểu", acc: ["thời khóa biểu", "tkb"], why: "Thời khoá biểu giúp học sinh chuẩn bị sách vở." },
  { id: "R2-176", lv: 1, tp: "vocab", h: ["Dải lụa đỏ thắt quanh cổ của đội viên.", "Danh từ ba tiếng, là một góc của lá cờ Tổ quốc.", "Tiếng đầu là “khăn”."], a: "khăn quàng đỏ", acc: ["khăn quàng"], why: "Khăn quàng đỏ là biểu tượng của Đội Thiếu niên Tiền phong Hồ Chí Minh." },
  { id: "R2-177", lv: 1, tp: "vocab", h: ["Cuộc thi chạy, nhảy, ném… của học sinh toàn trường, thường vào mùa xuân.", "Gồm bốn tiếng, mang tên người anh hùng làng Gióng.", "Tiếng đầu là “hội”."], a: "hội khoẻ Phù Đổng", acc: ["hội khỏe Phù Đổng", "hội thao", "đại hội thể dục thể thao"], why: "Hội khoẻ Phù Đổng mang tên Thánh Gióng (Phù Đổng Thiên Vương)." },
  { id: "R2-178", lv: 1, tp: "vocab", h: ["Đồ dùng có hai mũi nhọn, dùng để cắt giấy, cắt vải.", "Danh từ một hoặc hai tiếng.", "Tiếng đầu là “cái”."], a: "cái kéo", acc: ["kéo", "chiếc kéo"], why: "Kéo có hai lưỡi bắt chéo nhau để cắt." },
  { id: "R2-179", lv: 1, tp: "vocab", h: ["Dụng cụ để đóng đinh, đầu bằng sắt, có cán.", "Danh từ một hoặc hai tiếng.", "Tiếng đầu là “cái”."], a: "cái búa", acc: ["búa", "chiếc búa"], why: "Búa dùng để đóng, đập." },
  { id: "R2-180", lv: 1, tp: "vocab", h: ["Đồ dùng dài, có lá hoặc sợi bó lại, để quét nhà.", "Danh từ một hoặc hai tiếng.", "Tiếng đầu là “cái”."], a: "cái chổi", acc: ["chổi", "chiếc chổi"], why: "Chổi dùng để quét bụi bẩn." },
  { id: "R2-181", lv: 1, tp: "vocab", h: ["Con vật nhỏ bò sát, hay bò trên tường, kêu “chậc chậc”, đứt đuôi vẫn sống.", "Danh từ chỉ con vật.", "Tiếng đầu là “con”."], a: "con thạch sùng", acc: ["thạch sùng", "con thằn lằn nhà"], why: "Thạch sùng (thằn lằn nhà) bắt muỗi, côn trùng." },
  { id: "R2-182", lv: 1, tp: "vocab", h: ["Loài chim lông đen, hót rất hay, có thể bắt chước tiếng người.", "Danh từ hai tiếng.", "Tiếng đầu là “chim”."], a: "chim sáo", acc: ["sáo", "con sáo", "sáo sậu"], why: "Chim sáo thông minh, có thể học nói vài tiếng." },
  { id: "R2-183", lv: 1, tp: "vocab", h: ["Con vật sống ở cực Bắc, lông trắng muốt, rất to khoẻ.", "Danh từ ba tiếng.", "Tiếng đầu là “gấu”."], a: "gấu Bắc Cực", acc: ["gấu trắng"], why: "Gấu Bắc Cực sống trên băng, giỏi bơi lội." },
  { id: "R2-184", lv: 1, tp: "vocab", h: ["Người làm ra những bức tượng bằng đá, gỗ, đồng.", "Danh từ ba tiếng.", "Tiếng đầu là “nhà”."], a: "nhà điêu khắc", acc: ["điêu khắc gia"], why: "Nhà điêu khắc tạo hình khối bằng cách đẽo, nặn, đúc." },
  { id: "R2-185", lv: 1, tp: "vocab", h: ["Người làm việc trên công trường, xây nhà, xây tường.", "Danh từ hai tiếng.", "Tiếng đầu là “thợ”."], a: "thợ xây", acc: ["thợ hồ"], why: "Thợ xây (thợ hồ) dựng nên những ngôi nhà." },
  { id: "R2-186", lv: 1, tp: "vocab", h: ["Người mang thư từ, bưu phẩm của bưu điện đến tận từng nhà.", "Danh từ ba tiếng.", "Tiếng đầu là “người”."], a: "người đưa thư", acc: ["bưu tá"], why: "Người đưa thư (bưu tá) làm việc cho bưu điện." },
  { id: "R2-187", lv: 1, tp: "vocab", h: ["Người bán thuốc, hướng dẫn cách dùng thuốc theo đơn.", "Danh từ hai tiếng, gốc Hán Việt.", "Tiếng đầu là “dược”."], a: "dược sĩ", acc: ["dược sỹ"], why: "Dược sĩ có chuyên môn về thuốc." },
  { id: "R2-188", lv: 1, tp: "vocab", h: ["Ngôi nhà nhỏ có lối thoát, nơi chú chó ngủ.", "Danh từ hai tiếng.", "Tiếng đầu là “chuồng”."], a: "chuồng chó", acc: ["cũi chó"], why: "Chuồng chó che mưa gió cho chó." },
  { id: "R2-189", lv: 1, tp: "vocab", h: ["Lễ hội đêm rằm tháng tám, trẻ em rước đèn, phá cỗ.", "Đêm ấy trăng tròn và sáng nhất năm.", "Gồm ba tiếng, tiếng đầu là “Tết”."], a: "Tết Trung thu", acc: ["rằm tháng tám"], why: "Tết Trung thu là tết của thiếu nhi." },
  { id: "R2-190", lv: 1, tp: "vocab", fam: "traucau", h: ["Loài cây thân cột, lá to xoè như chiếc quạt, quả chín màu đỏ hoặc vàng, dùng ăn với trầu.", "Trong sự tích trầu cau, người anh hoá thành cây này.", "Tiếng đầu là “cây”."], a: "cây cau", acc: ["cau", "quả cau"], why: "Miếng trầu, quả cau là đầu câu chuyện của người Việt." },
];

const MEDIUM: Clue[] = [
  { id: "R2-201", lv: 2, tp: "vocab", h: ["Phần việc mình phải làm và phải chịu hậu quả nếu làm không tốt.", "Danh từ Hán Việt hai tiếng.", "Tiếng đầu là “trách”."], a: "trách nhiệm", why: "Người có trách nhiệm luôn làm tròn phần việc của mình." },
  { id: "R2-202", lv: 2, tp: "vocab", h: ["Những quy định chung buộc mọi người trong tập thể phải tuân theo.", "Trường học, quân đội đều coi trọng điều này.", "Tiếng đầu là “kỷ”."], a: "kỷ luật", acc: ["kỉ luật"], why: "Kỷ luật giúp tập thể vận hành nề nếp." },
  { id: "R2-203", lv: 2, tp: "vocab", h: ["Kính trọng, coi trọng người khác hoặc điều gì đó.", "Trái nghĩa với “coi thường”.", "Tiếng đầu là “tôn”."], a: "tôn trọng", why: "Tôn trọng là đánh giá đúng, đối xử đúng mực với người khác." },
  { id: "R2-204", lv: 2, tp: "vocab", fam: "anqua", h: ["Nhớ ơn và trân trọng công lao người đã giúp mình.", "Trái nghĩa với “vô ơn”.", "Tiếng đầu là “biết”."], a: "biết ơn", why: "Biết ơn là đạo lý “uống nước nhớ nguồn”." },
  { id: "R2-205", lv: 2, tp: "vocab", h: ["Hết lòng kính yêu, chăm sóc cha mẹ, ông bà.", "Tính từ Hán Việt hai tiếng.", "Tiếng đầu là “hiếu”."], a: "hiếu thảo", acc: ["hiếu thuận"], why: "Hiếu thảo là đạo làm con." },
  { id: "R2-206", lv: 2, tp: "vocab", h: ["Vững vàng, không chịu khuất phục trước khó khăn, kẻ thù.", "Tính từ Hán Việt hai tiếng.", "Tiếng đầu là “kiên”."], a: "kiên cường", acc: ["bất khuất"], why: "Kiên cường là cứng cỏi, không lùi bước." },
  { id: "R2-207", lv: 2, tp: "vocab", h: ["Kéo dài liên tục, không nản, không giảm sức.", "Từ láy hai tiếng.", "Tiếng đầu là “bền”."], a: "bền bỉ", why: "Bền bỉ là bền lâu và đều đặn." },
  { id: "R2-208", lv: 2, tp: "vocab", fam: "siengnang", h: ["Có tài năng, trí tuệ vượt trội hơn người.", "Tính từ hai tiếng, gần nghĩa với “tài giỏi”.", "Tiếng đầu là “thông”."], a: "thông minh", acc: ["sáng dạ"], why: "Thông minh là nhanh hiểu, sáng trí." },
  { id: "R2-209", lv: 2, tp: "vocab", fam: "haophong", h: ["Sẵn lòng giúp đỡ người khác mà không tính toán thiệt hơn.", "Danh từ hoặc tính từ, gốc Hán Việt.", "Tiếng đầu là “hào”."], a: "hào phóng", acc: ["rộng rãi"], why: "Hào phóng là rộng rãi trong cho tặng, chi tiêu." },
  { id: "R2-210", lv: 2, tp: "vocab", h: ["Chỉ nghĩ đến lợi ích của riêng mình.", "Trái nghĩa với “vị tha”.", "Tiếng đầu là “ích”."], a: "ích kỷ", acc: ["ích kỉ"], why: "Ích kỷ: “ích” là lợi, “kỷ” là mình." },
  { id: "R2-211", lv: 2, tp: "vocab", fam: "kieucang", h: ["Tự cho mình hơn người, coi thường người khác.", "Trái nghĩa với “khiêm tốn”.", "Tiếng đầu là “kiêu”."], a: "kiêu ngạo", acc: ["kiêu căng", "tự cao", "ngạo mạn"], why: "Kiêu ngạo dễ khiến người khác xa lánh." },
  { id: "R2-212", lv: 2, tp: "vocab", h: ["Không dám làm việc gì vì sợ hãi, thiếu can đảm.", "Trái nghĩa với “dũng cảm”.", "Tiếng đầu là “hèn”."], a: "hèn nhát", acc: ["nhút nhát", "nhát gan"], why: "Hèn nhát là thiếu dũng khí." },
  { id: "R2-213", lv: 2, tp: "vocab", h: ["Không nhớ ơn người đã giúp đỡ mình.", "Trái nghĩa với “biết ơn”.", "Tiếng đầu là “vô”."], a: "vô ơn", acc: ["bạc bẽo", "vong ơn"], why: "Vô ơn bị dân gian chê là “ăn cháo đá bát”." },
  { id: "R2-214", lv: 2, tp: "vocab", h: ["Dùng quá mức cần thiết, gây phí phạm.", "Trái nghĩa với “tiết kiệm”.", "Tiếng đầu là “lãng”."], a: "lãng phí", acc: ["phung phí", "hoang phí"], why: "Lãng phí là dùng hoang, bỏ phí của cải, thời gian." },
  { id: "R2-215", lv: 2, tp: "vocab", h: ["Hăng hái, sốt sắng muốn làm việc gì đó.", "Tính từ hai tiếng, gần nghĩa với “say mê”.", "Tiếng đầu là “nhiệt”."], a: "nhiệt tình", acc: ["nhiệt huyết"], why: "Nhiệt tình là đem hết sức mình ra làm." },
  { id: "R2-216", lv: 2, tp: "vocab", h: ["Thật lòng, không giả dối.", "Gần nghĩa với “thành thật”.", "Tiếng đầu là “chân”."], a: "chân thật", acc: ["thành thật", "thật lòng"], why: "Chân thật là ngay thẳng, không giả tạo." },
  { id: "R2-217", lv: 2, tp: "vocab", h: ["Giữ được bình tĩnh, không nóng vội, không hấp tấp.", "Tính từ hai tiếng, gốc Hán Việt.", "Tiếng đầu là “điềm”."], a: "điềm tĩnh", acc: ["điềm đạm", "bình tĩnh"], why: "Người điềm tĩnh xử lý việc gấp vẫn sáng suốt." },
  { id: "R2-218", lv: 2, tp: "vocab", h: ["Ý muốn mạnh mẽ đạt được điều tốt đẹp, lớn lao.", "Danh từ hai tiếng, gần nghĩa với “ước mơ lớn”.", "Tiếng đầu là “khát”."], a: "khát vọng", acc: ["hoài bão"], why: "Khát vọng là mong muốn mãnh liệt." },
  { id: "R2-219", lv: 2, tp: "vocab", h: ["Thói quen sinh hoạt lâu đời được cả cộng đồng làm theo.", "“… tập quán” là cụm từ quen dùng.", "Tiếng đầu là “phong”."], a: "phong tục", acc: ["tập tục"], why: "Phong tục là nếp sống được truyền từ đời này qua đời khác." },
  { id: "R2-220", lv: 2, tp: "vocab", h: ["Thích tiếp đón, đãi đằng khách đến chơi nhà.", "Tính từ Hán Việt hai tiếng.", "Tiếng đầu là “hiếu”."], a: "hiếu khách", why: "Người Việt nổi tiếng hiếu khách." },
  { id: "R2-221", lv: 2, tp: "vocab", h: ["Lịch sự, tao nhã, có văn hoá trong cách ăn mặc, cư xử.", "Người Tràng An xưa được khen bằng từ này.", "Tiếng đầu là “thanh”."], a: "thanh lịch", acc: ["lịch sự", "thanh nhã"], why: "“Chẳng thơm cũng thể hoa nhài, dẫu không thanh lịch cũng người Tràng An.”" },
  { id: "R2-222", lv: 2, tp: "vocab", h: ["Tự nhiên, giản dị, không màu mè, không cầu kỳ.", "Thường dùng để khen người nhà quê hiền lành.", "Tiếng đầu là “mộc”."], a: "mộc mạc", acc: ["chất phác"], why: "Mộc mạc như gỗ chưa sơn — giữ vẻ tự nhiên." },
  { id: "R2-223", lv: 2, tp: "vocab", h: ["Khả năng chịu trách nhiệm, tự quyết định và vượt khó, không dễ bị lung lay.", "Danh từ Hán Việt hai tiếng.", "Tiếng đầu là “bản”."], a: "bản lĩnh", why: "Người có bản lĩnh vững vàng trước thử thách." },
  { id: "R2-224", lv: 2, tp: "vocab", h: ["Biết hy sinh lợi ích của mình vì người khác.", "Trái nghĩa với “ích kỷ”.", "Tiếng đầu là “vị”."], a: "vị tha", why: "Vị tha: “vị” là vì, “tha” là người khác." },
  { id: "R2-225", lv: 2, tp: "vocab", h: ["Ghen ghét, khó chịu khi thấy người khác hơn mình.", "Danh từ hoặc động từ hai tiếng.", "Tiếng đầu là “đố”."], a: "đố kỵ", acc: ["đố kị", "ghen tị", "ganh tị"], why: "Đố kỵ khiến con người nhỏ nhen." },
  { id: "R2-226", lv: 2, tp: "vocab", h: ["Hết lòng hết sức với công việc, không ngại khó khăn.", "Tính từ hai tiếng, gần nghĩa với “tận tâm”.", "Tiếng đầu là “tận”."], a: "tận tuỵ", acc: ["tận tụy", "tận tâm"], why: "Thầy cô tận tuỵ với học trò." },
  { id: "R2-227", lv: 2, tp: "vocab", fam: "canthan", h: ["Lo lắng, chăm sóc kỹ càng mọi việc, không bỏ sót điều gì.", "Tính từ hai tiếng.", "Tiếng đầu là “chu”."], a: "chu đáo", why: "Chu đáo là chăm lo đầy đủ, cẩn thận." },
  { id: "R2-228", lv: 2, tp: "vocab", h: ["Sáng suốt, nhanh nhạy trong suy nghĩ dù tuổi cao.", "Tính từ Hán Việt hai tiếng.", "Tiếng đầu là “minh”."], a: "minh mẫn", why: "Ông bà còn minh mẫn là niềm vui của con cháu." },
  { id: "R2-229", lv: 2, tp: "vocab", h: ["Tài giỏi vượt hẳn mọi người, ít ai sánh kịp.", "Tính từ Hán Việt hai tiếng, gần nghĩa với “kiệt xuất”.", "Tiếng đầu là “lỗi”."], a: "lỗi lạc", acc: ["kiệt xuất", "xuất chúng"], why: "Lỗi lạc dùng để khen những người tài năng lớn." },
  { id: "R2-230", lv: 2, tp: "vocab", h: ["Dòng dõi, những thế hệ con cháu tiếp nối nhau trong một họ.", "Danh từ Hán Việt hai tiếng, gần nghĩa với “dòng họ”.", "Tiếng đầu là “gia”."], a: "gia tộc", acc: ["dòng tộc", "dòng họ"], why: "Gia tộc gồm nhiều gia đình cùng một tổ tiên." },
  { id: "R2-231", lv: 2, tp: "vocab", h: ["Nhớ lại, nghĩ về những điều tốt đẹp đã qua.", "Danh từ hoặc động từ Hán Việt hai tiếng.", "Tiếng đầu là “hoài”."], a: "hoài niệm", acc: ["hồi tưởng"], why: "Hoài niệm là nhớ về quá khứ với nhiều cảm xúc." },
  { id: "R2-232", lv: 2, tp: "vocab", h: ["Chuyển từ nơi này sang nơi khác để sinh sống lâu dài.", "Động từ Hán Việt hai tiếng.", "Tiếng đầu là “di”."], a: "di cư", acc: ["di dân"], why: "Chim én di cư tránh rét; con người cũng di cư tìm nơi sống mới." },
  { id: "R2-233", lv: 2, tp: "vocab", h: ["Chất đất màu mỡ do sông bồi đắp hai bên bờ.", "Sông Hồng, sông Cửu Long mang về rất nhiều.", "Tiếng đầu là “phù”."], a: "phù sa", why: "Phù sa làm đồng bằng màu mỡ." },
  { id: "R2-234", lv: 2, tp: "vocab", h: ["Hiện tượng nước biển dâng lên rồi rút xuống theo giờ trong ngày.", "Do sức hút của Mặt Trăng gây ra.", "Tiếng đầu là “thuỷ”."], a: "thuỷ triều", acc: ["thủy triều", "nước triều"], why: "Thuỷ triều lên xuống theo chu kỳ." },
  { id: "R2-235", lv: 2, tp: "vocab", h: ["Vùng đất bằng phẳng, rộng lớn, thấp, thuận lợi trồng lúa.", "Sông Hồng và sông Cửu Long đều bồi đắp nên một vùng như vậy.", "Tiếng đầu là “đồng”."], a: "đồng bằng", why: "Đồng bằng là vựa lúa của cả nước." },
  { id: "R2-236", lv: 2, tp: "vocab", h: ["Vùng đất cao, rộng, mặt tương đối bằng phẳng.", "Lâm Viên, Mộc Châu là ví dụ.", "Tiếng đầu là “cao”."], a: "cao nguyên", why: "Cao nguyên khí hậu mát mẻ, hợp trồng chè, cà phê." },
  { id: "R2-237", lv: 2, tp: "vocab", h: ["Phần đất nhô ra biển, ba mặt giáp nước.", "Cà Mau có mũi đất kiểu này.", "Tiếng đầu là “bán”."], a: "bán đảo", why: "“Bán” là một nửa: bán đảo gần như một hòn đảo." },
  { id: "R2-238", lv: 2, tp: "vocab", h: ["Đường tưởng tượng chia Trái Đất thành nửa cầu Bắc và nửa cầu Nam.", "Nơi đây quanh năm nóng.", "Tiếng đầu là “xích”."], a: "xích đạo", why: "Xích đạo là vĩ tuyến dài nhất, vĩ độ 0." },
  { id: "R2-239", lv: 2, tp: "vocab", h: ["Quá trình cây xanh dùng ánh sáng mặt trời để tạo chất dinh dưỡng, nhả ra khí ô xi.", "Diễn ra ở lá, nhờ chất diệp lục.", "Tiếng đầu là “quang”."], a: "quang hợp", why: "“Quang” là ánh sáng, “hợp” là tổng hợp." },
  { id: "R2-240", lv: 2, tp: "vocab", h: ["Vật hút được sắt, có hai cực Bắc và Nam.", "Kim la bàn được làm từ thứ này.", "Tiếng đầu là “nam”."], a: "nam châm", why: "Nam châm hút sắt, thép." },
  { id: "R2-241", lv: 2, tp: "vocab", h: ["Hiện tượng Mặt Trăng che khuất Mặt Trời, trời tối sầm giữa ban ngày.", "Danh từ Hán Việt hai tiếng.", "Tiếng cuối là “thực”."], a: "nhật thực", why: "Nhật thực xảy ra khi Mặt Trăng nằm giữa Trái Đất và Mặt Trời." },
  { id: "R2-242", lv: 2, tp: "vocab", h: ["Hiện tượng Trái Đất che bóng lên Mặt Trăng.", "Khi ấy trăng có thể chuyển màu đỏ sẫm.", "Tiếng cuối là “thực”."], a: "nguyệt thực", why: "“Nguyệt” là mặt trăng." },
  { id: "R2-243", lv: 2, tp: "vocab", h: ["Dấu vết sinh vật cổ còn lưu lại trong đá.", "Xương khủng long là ví dụ.", "Tiếng đầu là “hoá”."], a: "hoá thạch", acc: ["hóa thạch"], why: "Hoá thạch giúp nghiên cứu sự sống thời xa xưa." },
  { id: "R2-244", lv: 2, tp: "vocab", h: ["Ngành khoa học tìm hiểu lịch sử qua di vật đào được dưới đất.", "Danh từ Hán Việt hai tiếng.", "Tiếng cuối là “cổ”."], a: "khảo cổ", acc: ["khảo cổ học"], why: "Khảo cổ học giúp tìm ra trống đồng, mộ cổ…" },
  { id: "R2-245", lv: 2, tp: "vocab", h: ["Tài sản văn hoá, thiên nhiên quý giá của thế hệ trước để lại.", "Vịnh Hạ Long được UNESCO công nhận là một trong số đó.", "Tiếng đầu là “di”."], a: "di sản", why: "Di sản cần được gìn giữ cho mai sau." },
  { id: "R2-246", lv: 2, tp: "vocab", h: ["Ngôi nhà chung của làng xưa, thờ Thành hoàng, nơi họp việc làng.", "“… làng” là cụm từ quen thuộc.", "Một tiếng, bắt đầu bằng “đ”."], a: "đình", acc: ["đình làng", "ngôi đình"], why: "Đình làng là trung tâm sinh hoạt của làng xưa." },
  { id: "R2-247", lv: 2, tp: "vocab", h: ["Nghệ thuật viết chữ đẹp bằng bút lông, mực tàu.", "Ông đồ ngày Tết thường làm việc này.", "Tiếng đầu là “thư”."], a: "thư pháp", why: "Thư pháp là nghệ thuật viết chữ đẹp." },
  { id: "R2-248", lv: 2, tp: "lit", h: ["Loại hình sân khấu dân gian của đồng bằng Bắc Bộ, có các vai hề, đào, kép.", "“Quan Âm Thị Kính” là vở nổi tiếng.", "Một tiếng, bắt đầu bằng “ch”."], a: "chèo", acc: ["hát chèo"], why: "Chèo là nghệ thuật sân khấu truyền thống lâu đời." },
  { id: "R2-249", lv: 2, tp: "lit", h: ["Hai câu văn đối nhau về ý và chữ, thường treo trong nhà dịp Tết.", "“Thịt mỡ, dưa hành, … đỏ.”", "Tiếng đầu là “câu”."], a: "câu đối", why: "Câu đối đỏ là thú chơi Tết của người xưa." },
  { id: "R2-250", lv: 2, tp: "lit", h: ["Người đỗ đầu kỳ thi Đình thời phong kiến.", "Mạc Đĩnh Chi, Lương Thế Vinh từng đỗ danh hiệu này.", "Tiếng đầu là “trạng”."], a: "trạng nguyên", why: "Trạng nguyên đứng đầu bảng tiến sĩ." },
  { id: "R2-251", lv: 2, tp: "lit", h: ["Tranh dân gian in trên giấy dó, nổi tiếng với “Đám cưới chuột”, “Lợn ăn cây ráy”.", "Tên làng ở Bắc Ninh.", "Gồm ba tiếng, tiếng đầu là “tranh”."], a: "tranh Đông Hồ", why: "Tranh Đông Hồ in bằng ván khắc gỗ, màu từ thiên nhiên." },
  { id: "R2-252", lv: 2, tp: "vocab", h: ["Công trình hoặc cảnh vật đẹp, hùng vĩ hiếm có, khiến người ta thán phục.", "Vịnh Hạ Long từng được bầu là một trong bảy … thiên nhiên mới của thế giới.", "Tiếng đầu là “kỳ”."], a: "kỳ quan", acc: ["kì quan"], why: "“Kỳ” là lạ, “quan” là cảnh để xem." },
  { id: "R2-253", lv: 2, tp: "vocab", h: ["Nơi có cảnh đẹp nổi tiếng, nhiều người tìm đến thăm.", "Cụm bốn tiếng, hay đi cùng “di tích lịch sử”.", "Tiếng đầu là “danh”."], a: "danh lam thắng cảnh", acc: ["danh lam", "thắng cảnh", "danh thắng"], why: "Danh lam thắng cảnh là cảnh đẹp nổi danh." },
  { id: "R2-254", lv: 2, tp: "vocab", h: ["Hoạt động văn hoá cộng đồng gồm phần nghi thức cúng tế và phần vui chơi.", "Hội Lim, hội Gióng là ví dụ.", "Tiếng đầu là “lễ”."], a: "lễ hội", why: "Lễ hội thường diễn ra vào mùa xuân." },
  { id: "R2-255", lv: 2, tp: "vocab", h: ["Làng có nhiều hộ cùng làm một nghề thủ công truyền thống.", "Bát Tràng làm gốm, Vạn Phúc dệt lụa.", "Tiếng đầu là “làng”."], a: "làng nghề", acc: ["làng nghề truyền thống"], why: "Làng nghề giữ gìn tinh hoa thủ công Việt." },
  { id: "R2-256", lv: 2, tp: "lit", h: ["Người kể lại câu chuyện trong tác phẩm.", "Có thể xưng “tôi” hoặc giấu mình.", "Tiếng đầu là “người”."], a: "người kể chuyện", why: "Người kể chuyện dẫn dắt người đọc theo dõi câu chuyện." },
  { id: "R2-257", lv: 2, tp: "vocab", h: ["Đồ vật làm từ đất sét nung ở nhiệt độ cao như bát, đĩa, bình hoa.", "Bát Tràng, Chu Đậu nổi tiếng với nghề này.", "Tiếng đầu là “gốm”."], a: "gốm sứ", acc: ["đồ gốm", "gốm"], why: "Gốm là đất nung; sứ là loại gốm trắng mịn, nung ở nhiệt độ cao hơn." },
  { id: "R2-258", lv: 2, tp: "vocab", h: ["Tranh vẽ bằng nhựa cây sơn, phủ nhiều lớp rồi mài cho nhẵn bóng.", "Một chất liệu hội hoạ độc đáo của Việt Nam.", "Tiếng đầu là “sơn”."], a: "sơn mài", acc: ["tranh sơn mài"], why: "Sơn mài thường dùng vàng, bạc, vỏ trứng để tạo màu." },
  { id: "R2-259", lv: 2, tp: "vocab", h: ["Nghề gắn những mảnh vỏ trai, ốc óng ánh lên đồ gỗ thành hình trang trí.", "Danh từ hai tiếng.", "Tiếng đầu là “khảm”."], a: "khảm trai", acc: ["khảm xà cừ"], why: "Khảm trai làm đồ gỗ thêm lấp lánh." },
  { id: "R2-260", lv: 2, tp: "lit", h: ["Lời nói, câu văn mượn của người khác, đặt trong ngoặc kép.", "Danh từ hai tiếng.", "Tiếng đầu là “trích”."], a: "trích dẫn", acc: ["lời dẫn"], why: "Trích dẫn giúp bài viết có căn cứ." },
  { id: "R2-261", lv: 2, tp: "spell", h: ["Dấu câu đặt cuối câu hỏi.", "Hình như một cái móc có chấm bên dưới.", "Tiếng đầu là “dấu”."], a: "dấu chấm hỏi", acc: ["dấu hỏi chấm", "chấm hỏi"], why: "Dấu chấm hỏi dùng cho câu nghi vấn." },
  { id: "R2-262", lv: 2, tp: "spell", h: ["Dấu câu đặt cuối câu cảm hoặc câu khiến.", "Một gạch dọc có chấm bên dưới.", "Tiếng đầu là “dấu”."], a: "dấu chấm than", acc: ["dấu chấm cảm", "chấm than"], why: "Dấu chấm than bộc lộ cảm xúc hoặc yêu cầu." },
  { id: "R2-263", lv: 2, tp: "spell", h: ["Dấu câu gồm hai chấm tròn chồng lên nhau.", "Đặt trước lời nói trực tiếp hoặc phần liệt kê.", "Tiếng đầu là “dấu”."], a: "dấu hai chấm", why: "Dấu hai chấm báo hiệu phần giải thích, liệt kê." },
  { id: "R2-264", lv: 2, tp: "spell", h: ["Chữ cái viết to ở đầu câu và đầu tên riêng.", "Danh từ hai tiếng.", "Tiếng đầu là “chữ”."], a: "chữ hoa", acc: ["chữ in hoa", "chữ viết hoa"], why: "Viết hoa đầu câu và tên riêng là quy tắc chính tả." },
  { id: "R2-265", lv: 2, tp: "vocab", h: ["Trang phục truyền thống của phụ nữ Bắc Bộ xưa, thân áo có bốn vạt.", "Liền chị quan họ thường mặc khi hát.", "Tiếng đầu là “áo”."], a: "áo tứ thân", why: "“Tứ thân” là bốn thân (vạt) áo." },
  { id: "R2-266", lv: 2, tp: "vocab", h: ["Từ gồm các tiếng có nghĩa ghép lại với nhau.", "“Quần áo”, “xe đạp” là ví dụ.", "Tiếng đầu là “từ”."], a: "từ ghép", why: "Từ ghép tạo bởi các tiếng có quan hệ về nghĩa." },
  { id: "R2-267", lv: 2, tp: "vocab", h: ["Chiếc khăn kẻ ô đen trắng quen thuộc của người Nam Bộ.", "Thường quàng cổ hoặc vắt vai.", "Tiếng đầu là “khăn”."], a: "khăn rằn", why: "Khăn rằn gắn với hình ảnh người dân miền Tây sông nước." },
  { id: "R2-268", lv: 2, tp: "vocab", h: ["Chợ chỉ họp vào những ngày nhất định, nhất là ở vùng cao.", "Bắc Hà, Đồng Văn nổi tiếng với loại chợ này.", "Tiếng đầu là “chợ”."], a: "chợ phiên", why: "Chợ phiên vùng cao vừa để mua bán vừa để gặp gỡ." },
  { id: "R2-269", lv: 2, tp: "vocab", h: ["Ngôi nhà dựng trên những cột cao, cách mặt đất, của đồng bào miền núi.", "Gầm nhà có thể để nông cụ, củi đuốc.", "Tiếng đầu là “nhà”."], a: "nhà sàn", why: "Nhà sàn tránh ẩm thấp, thú dữ." },
  { id: "R2-270", lv: 2, tp: "vocab", h: ["Ngôi nhà chung có mái cao vút như lưỡi rìu của buôn làng Tây Nguyên.", "Nơi tụ họp, tiếp khách, tổ chức lễ hội.", "Tiếng đầu là “nhà”."], a: "nhà rông", why: "Nhà rông là biểu tượng của làng Tây Nguyên." },
  { id: "R2-271", lv: 2, tp: "vocab", h: ["Những ô ruộng ven biển, người ta phơi nước biển để lấy muối.", "Diêm dân làm việc ở đây.", "Tiếng đầu là “ruộng”."], a: "ruộng muối", acc: ["đồng muối"], why: "Nắng càng to, muối càng nhiều." },
  { id: "R2-272", lv: 2, tp: "vocab", h: ["Tình cảm gắn bó, yêu thương giữa những người bạn.", "Danh từ hai tiếng.", "Tiếng đầu là “tình”."], a: "tình bạn", acc: ["tình bằng hữu", "hữu nghị"], why: "Tình bạn đẹp cần được vun đắp bằng sự chân thành." },
  { id: "R2-273", lv: 2, tp: "vocab", h: ["Chủ động làm tốt việc của mình mà không cần ai nhắc nhở, ép buộc.", "Tính từ hai tiếng.", "Tiếng đầu là “tự”."], a: "tự giác", why: "Tự giác là chủ động làm việc của mình." },
  { id: "R2-274", lv: 2, tp: "vocab", h: ["Biết tự lo liệu, không dựa dẫm vào người khác.", "Tính từ hai tiếng, gần nghĩa với “tự lực”.", "Tiếng đầu là “tự”."], a: "tự lập", acc: ["tự lực"], why: "Tự lập giúp ta trưởng thành." },
  { id: "R2-275", lv: 2, tp: "vocab", h: ["Đoàn người đi bộ diễu qua đường phố trong ngày lễ.", "Động từ hoặc danh từ hai tiếng.", "Tiếng đầu là “diễu”."], a: "diễu hành", acc: ["duyệt binh"], why: "Diễu hành là hoạt động thường có trong các ngày lễ lớn." },
  { id: "R2-276", lv: 2, tp: "vocab", h: ["Hoạt động làm việc tốt không lấy tiền, vì cộng đồng.", "Danh từ hoặc tính từ Hán Việt hai tiếng.", "Tiếng đầu là “tình”."], a: "tình nguyện", acc: ["thiện nguyện", "tự nguyện"], why: "Thanh niên tình nguyện giúp đỡ cộng đồng." },
  { id: "R2-277", lv: 2, tp: "vocab", h: ["Rác thải, khói bụi làm không khí, nguồn nước bẩn và độc hại.", "Danh từ hai tiếng.", "Tiếng đầu là “ô”."], a: "ô nhiễm", why: "Ô nhiễm môi trường ảnh hưởng tới sức khoẻ." },
  { id: "R2-278", lv: 2, tp: "vocab", h: ["Biến rác, đồ cũ thành vật dụng mới để dùng lại.", "Động từ Hán Việt hai tiếng.", "Tiếng đầu là “tái”."], a: "tái chế", why: "Tái chế giúp giảm rác thải." },
  { id: "R2-279", lv: 2, tp: "vocab", h: ["Giải thưởng cao nhất trong một cuộc thi.", "Danh từ hai tiếng, gốc Hán Việt.", "Tiếng đầu là “quán”."], a: "quán quân", acc: ["vô địch", "giải nhất"], why: "Quán quân là người đứng đầu." },
  { id: "R2-280", lv: 2, tp: "vocab", h: ["Người hâm mộ, ủng hộ cổ vũ cho một đội bóng hay ca sĩ.", "Danh từ hai tiếng, gốc Hán Việt.", "Tiếng đầu là “cổ”."], a: "cổ động viên", acc: ["người hâm mộ", "fan"], why: "Cổ động viên tiếp thêm sức mạnh cho đội nhà." },
  { id: "R2-281", lv: 2, tp: "vocab", h: ["Cuộc thi đấu cuối cùng để chọn ra nhà vô địch.", "Danh từ hai tiếng.", "Tiếng đầu là “chung”."], a: "chung kết", why: "Chung kết là trận quyết định ngôi vô địch." },
  { id: "R2-282", lv: 2, tp: "vocab", h: ["Người điều khiển, phân xử trận đấu thể thao.", "Thường cầm còi và thẻ vàng, thẻ đỏ.", "Tiếng đầu là “trọng”."], a: "trọng tài", why: "Trọng tài bảo đảm trận đấu đúng luật." },
  { id: "R2-283", lv: 2, tp: "vocab", h: ["Sổ ghi chép hằng ngày những việc mình làm, mình nghĩ.", "Danh từ hai tiếng.", "Tiếng đầu là “nhật”."], a: "nhật ký", acc: ["nhật kí"], why: "Nhật ký giúp lưu giữ kỷ niệm và suy nghĩ." },
  { id: "R2-284", lv: 2, tp: "vocab", h: ["Bức ảnh hoặc tranh vẽ chân dung người, thường thấy trên bàn thờ.", "Danh từ hai tiếng.", "Tiếng đầu là “di”."], a: "di ảnh", why: "Di ảnh là ảnh người đã khuất." },
  { id: "R2-285", lv: 2, tp: "vocab", h: ["Lời dặn lại trước khi mất.", "Năm 1969, Bác Hồ để lại một văn bản như thế.", "Tiếng đầu là “di”."], a: "di chúc", why: "“Di chúc” của Bác Hồ là văn kiện thiêng liêng." },
  { id: "R2-286", lv: 2, tp: "vocab", h: ["Phương pháp chữa bệnh của người Việt dùng thảo mộc, kim châm.", "Tuệ Tĩnh, Hải Thượng Lãn Ông là danh y của ngành này.", "Tiếng đầu là “đông”."], a: "đông y", acc: ["y học cổ truyền", "thuốc nam", "thuốc bắc"], why: "Đông y dùng thảo dược và châm cứu." },
  { id: "R2-287", lv: 2, tp: "vocab", h: ["Danh hiệu, kỳ thi dành cho những học trò học tốt nhất các môn.", "Cụm từ ba tiếng.", "Tiếng đầu là “học”."], a: "học sinh giỏi", why: "Kỳ thi học sinh giỏi tôn vinh những tài năng." },
  { id: "R2-288", lv: 2, tp: "vocab", h: ["Bức tường đá dài nhất thế giới ở Trung Quốc.", "Gồm bốn tiếng, tiếng đầu là “Vạn”.", "Tiếng thứ ba là “Trường”."], a: "Vạn Lý Trường Thành", acc: ["Vạn Lí Trường Thành", "Trường Thành"], why: "“Vạn lý” là mười nghìn dặm, “trường thành” là bức tường dài." },
  { id: "R2-289", lv: 2, tp: "vocab", h: ["Cấu trúc khổng lồ bằng đá ở Ai Cập, nơi chôn cất các pharaoh.", "Danh từ ba tiếng.", "Tiếng đầu là “kim”."], a: "kim tự tháp", why: "Kim tự tháp có hình giống chữ “kim” (金) trong chữ Hán." },
  { id: "R2-290", lv: 2, tp: "vocab", h: ["Loài cây thân gỗ, lá kim, quanh năm xanh tốt, mọc nhiều ở Đà Lạt.", "Danh từ hai tiếng.", "Tiếng đầu là “cây”."], a: "cây thông", acc: ["thông", "rừng thông"], why: "Thông chịu lạnh tốt, là biểu tượng của Đà Lạt." },
];

const HARD: Clue[] = [
  { id: "R2-301", lv: 3, tp: "vocab", h: ["Người bạn hiểu thấu tâm hồn, hiểu cả tiếng lòng của mình.", "Gắn với điển tích Bá Nha gảy đàn, Tử Kỳ nghe hiểu.", "Tiếng đầu là “tri”."], a: "tri âm", acc: ["tri kỷ", "tri kỉ"], why: "“Tri âm” nghĩa đen là hiểu tiếng đàn." },
  { id: "R2-302", lv: 3, tp: "vocab", h: ["Đồng cỏ rộng mênh mông, ít cây to, khí hậu khô.", "Mông Cổ nổi tiếng với cảnh chăn ngựa trên vùng đất này.", "Tiếng đầu là “thảo”."], a: "thảo nguyên", why: "“Thảo” là cỏ, “nguyên” là cánh đồng rộng." },
  { id: "R2-303", lv: 3, tp: "vocab", h: ["Chỗ có nước và cây xanh giữa sa mạc.", "Đoàn lạc đà thường dừng chân ở đây.", "Tiếng đầu là “ốc”."], a: "ốc đảo", why: "Ốc đảo như hòn đảo xanh giữa biển cát." },
  { id: "R2-304", lv: 3, tp: "vocab", h: ["Vùng đất trũng, ngập nước quanh năm, nhiều bùn và cây cỏ.", "Danh từ hai tiếng.", "Tiếng đầu là “đầm”."], a: "đầm lầy", why: "Đầm lầy là nơi sinh sống của nhiều loài chim nước." },
  { id: "R2-305", lv: 3, tp: "vocab", h: ["Vùng đất bồi tụ ở cửa sông, có hình gần như tam giác.", "Sông Hồng, sông Cửu Long đều có vùng đất này.", "Tiếng đầu là “châu”."], a: "châu thổ", acc: ["tam giác châu", "đồng bằng châu thổ"], why: "Châu thổ màu mỡ nhờ phù sa." },
  { id: "R2-306", lv: 3, tp: "vocab", h: ["Dải nước hẹp nối hai vùng biển, nằm giữa hai khối đất.", "Ma-lắc-ca là một ví dụ nổi tiếng.", "Tiếng đầu là “eo”."], a: "eo biển", why: "Eo biển là đường đi quan trọng của tàu thuyền." },
  { id: "R2-307", lv: 3, tp: "vocab", h: ["Đường tưởng tượng nối cực Bắc với cực Nam trên quả địa cầu.", "Đường số 0 đi qua Grin-uých, nước Anh.", "Tiếng đầu là “kinh”."], a: "kinh tuyến", why: "Kinh tuyến dùng để xác định kinh độ." },
  { id: "R2-308", lv: 3, tp: "vocab", h: ["Hiện tượng thiếu nước kéo dài do lâu ngày không mưa.", "Đồng ruộng nứt nẻ, cây cối khô héo.", "Tiếng đầu là “hạn”."], a: "hạn hán", why: "Hạn hán gây mất mùa, thiếu nước sinh hoạt." },
  { id: "R2-309", lv: 3, tp: "vocab", h: ["Dòng lũ chảy xiết, ập đến rất nhanh ở vùng núi sau mưa lớn.", "Danh từ hai tiếng.", "Tiếng đầu là “lũ”."], a: "lũ quét", why: "Lũ quét cuốn trôi mọi thứ trên đường đi." },
  { id: "R2-310", lv: 3, tp: "vocab", h: ["Đất đá trên sườn đồi, bờ sông bị sụt, đổ xuống.", "Thường xảy ra sau mưa lớn kéo dài.", "Tiếng đầu là “sạt”."], a: "sạt lở", acc: ["sạt lở đất", "lở đất"], why: "Sạt lở đất gây nguy hiểm cho nhà cửa ven đồi." },
  { id: "R2-311", lv: 3, tp: "vocab", h: ["Lớp đất mặt bị nước mưa, dòng chảy cuốn trôi dần.", "Rừng đầu nguồn giúp ngăn hiện tượng này.", "Tiếng đầu là “xói”."], a: "xói mòn", why: "Xói mòn khiến đất bạc màu." },
  { id: "R2-312", lv: 3, tp: "lit", h: ["Âm nhạc cung đình triều Nguyễn, được UNESCO công nhận năm 2003.", "Gắn với cố đô Huế.", "Tiếng đầu là “nhã”."], a: "nhã nhạc", acc: ["nhã nhạc cung đình Huế"], why: "“Nhã nhạc” là âm nhạc tao nhã, dùng trong nghi lễ cung đình." },
  { id: "R2-313", lv: 3, tp: "lit", h: ["Loại hình hát thờ cúng Vua Hùng của vùng đất Phú Thọ.", "Được UNESCO ghi danh là di sản văn hoá phi vật thể.", "Tiếng đầu là “hát”."], a: "hát xoan", acc: ["xoan"], why: "Hát xoan thường diễn vào mùa xuân ở các miếu, đình Phú Thọ." },
  { id: "R2-314", lv: 3, tp: "lit", h: ["Sân khấu cổ truyền có mặt nạ vẽ màu, động tác ước lệ, đề cao trung hiếu.", "Đào Tấn là bậc thầy của loại hình này.", "Một tiếng, bắt đầu bằng “t”."], a: "tuồng", acc: ["hát bội", "hát tuồng"], why: "Tuồng (hát bội) phát triển mạnh ở miền Trung." },
  { id: "R2-315", lv: 3, tp: "vocab", h: ["Vị thần được thờ ở đình làng, che chở cho cả làng.", "Danh từ Hán Việt hai tiếng.", "Tiếng đầu là “thành”."], a: "thành hoàng", acc: ["thành hoàng làng"], why: "Mỗi làng xưa thờ một vị thành hoàng." },
  { id: "R2-316", lv: 3, tp: "vocab", h: ["Tấm biển gỗ khắc chữ lớn, treo ngang giữa nhà thờ, đình chùa.", "Thường đi cùng câu đối.", "Tiếng đầu là “hoành”."], a: "hoành phi", why: "“Hoành” là ngang; hoành phi treo ngang trên cao." },
  { id: "R2-317", lv: 3, tp: "lit", h: ["Danh hiệu dành cho người đỗ thứ hai trong kỳ thi Đình.", "Đứng sau trạng nguyên, trên thám hoa.", "Tiếng đầu là “bảng”."], a: "bảng nhãn", why: "Tam khôi gồm: trạng nguyên, bảng nhãn, thám hoa." },
  { id: "R2-318", lv: 3, tp: "lit", h: ["Danh hiệu dành cho người đỗ thứ ba trong kỳ thi Đình.", "Xếp sau trạng nguyên và bảng nhãn.", "Tiếng đầu là “thám”."], a: "thám hoa", why: "Thám hoa là người đứng thứ ba trong tam khôi." },
  { id: "R2-319", lv: 3, tp: "vocab", h: ["Người trí thức thời phong kiến có học vấn và khí tiết.", "Phan Bội Châu, Phan Châu Trinh là những người tiêu biểu.", "Tiếng đầu là “sĩ”."], a: "sĩ phu", why: "“Sĩ phu” là người học trò có danh vọng, chí khí." },
  { id: "R2-320", lv: 3, tp: "vocab", h: ["Người tài đức, giỏi giang được trọng dụng giúp nước.", "“… là nguyên khí của quốc gia” — lời khắc trên bia Văn Miếu.", "Tiếng đầu là “hiền”."], a: "hiền tài", why: "Thân Nhân Trung viết: “Hiền tài là nguyên khí của quốc gia.”" },
  { id: "R2-321", lv: 3, tp: "vocab", h: ["Người có tài năng và chí khí hơn người.", "Thường đi đôi với “anh hùng”: anh hùng …", "Tiếng đầu là “hào”."], a: "hào kiệt", why: "Hào kiệt chỉ người tài giỏi xuất chúng." },
  { id: "R2-322", lv: 3, tp: "vocab", h: ["Trong sạch, ngay thẳng, không tham ô, không làm điều sai trái.", "Tính từ Hán Việt hai tiếng.", "Tiếng đầu là “liêm”."], a: "liêm chính", acc: ["thanh liêm", "liêm khiết"], why: "“Cần, kiệm, liêm, chính” là bốn đức Bác Hồ dạy." },
  { id: "R2-323", lv: 3, tp: "vocab", h: ["Ngay thẳng, thật thà, không vì tình riêng mà làm sai lẽ phải.", "Tính từ Hán Việt hai tiếng.", "Tiếng đầu là “chính”."], a: "chính trực", acc: ["cương trực"], why: "Chu Văn An là tấm gương chính trực." },
  { id: "R2-324", lv: 3, tp: "vocab", h: ["Dám làm, dám chịu, quyết đoán và gan dạ.", "Tính từ Hán Việt hai tiếng.", "Tiếng đầu là “quả”."], a: "quả cảm", acc: ["can trường"], why: "“Quả” là quyết, “cảm” là dám." },
  { id: "R2-325", lv: 3, tp: "vocab", h: ["Giữ vững lập trường, ý chí, không dao động.", "Tính từ Hán Việt hai tiếng.", "Tiếng đầu là “kiên”."], a: "kiên định", why: "Kiên định là vững vàng theo đuổi mục tiêu." },
  { id: "R2-326", lv: 3, tp: "vocab", h: ["Có lòng thương yêu con người.", "Tính từ Hán Việt hai tiếng, gần nghĩa với “nhân hậu”.", "Tiếng đầu là “nhân”."], a: "nhân ái", acc: ["bác ái", "nhân từ"], why: "“Nhân” là lòng thương người, “ái” là yêu." },
  { id: "R2-327", lv: 3, tp: "vocab", h: ["Rộng lượng tha thứ cho lỗi lầm của người khác.", "Tính từ Hán Việt hai tiếng.", "Tiếng đầu là “khoan”."], a: "khoan dung", acc: ["độ lượng", "bao dung"], why: "Khoan dung giúp con người sống hoà hợp." },
  { id: "R2-328", lv: 3, tp: "vocab", h: ["Tỏ ra bình thường như không có chuyện gì xảy ra.", "Tính từ Hán Việt hai tiếng.", "Tiếng đầu là “thản”."], a: "thản nhiên", acc: ["bình thản"], why: "Thản nhiên là không bối rối, không lo âu." },
  { id: "R2-329", lv: 3, tp: "vocab", h: ["Thong thả, thanh thản, không vội vàng lo nghĩ.", "Từ láy hai tiếng.", "Tiếng đầu là “ung”."], a: "ung dung", acc: ["thong dong"], why: "Ung dung là phong thái thư thái, tự tại." },
  { id: "R2-330", lv: 3, tp: "vocab", fam: "boihoi", h: ["Xúc động, xao xuyến không yên khi nhớ về ai, điều gì.", "Từ láy hai tiếng, ca dao có câu “Nhớ ai bổi hổi …”.", "Tiếng đầu là “bồi”."], a: "bồi hồi", acc: ["bổi hổi bồi hồi"], why: "Bồi hồi là trạng thái lòng dạ xốn xang." },
  { id: "R2-331", lv: 3, tp: "vocab", h: ["Khóc nấc từng cơn, hơi thở đứt quãng.", "Từ láy hai tiếng.", "Tiếng đầu là “thổn”."], a: "thổn thức", why: "Thổn thức còn chỉ lòng xúc động, không yên." },
  { id: "R2-332", lv: 3, tp: "vocab", h: ["Băn khoăn, ân hận mãi không nguôi.", "Từ láy hai tiếng.", "Tiếng đầu là “day”."], a: "day dứt", why: "Day dứt là cứ vấn vương, không dứt ra được." },
  { id: "R2-333", lv: 3, tp: "vocab", h: ["Mục đích cao đẹp mà con người hướng tới, phấn đấu suốt đời.", "Danh từ Hán Việt hai tiếng.", "Tiếng đầu là “lý”."], a: "lý tưởng", acc: ["lí tưởng"], why: "Sống có lý tưởng là sống có mục đích." },
  { id: "R2-334", lv: 3, tp: "vocab", h: ["Niềm tin vào các vị thần thánh, thế lực siêu nhiên và việc thờ cúng.", "Thờ cúng tổ tiên là một ví dụ ở người Việt.", "Tiếng đầu là “tín”."], a: "tín ngưỡng", why: "Tín ngưỡng gắn với đời sống tâm linh." },
  { id: "R2-335", lv: 3, tp: "vocab", h: ["Hiền lành, nhân từ, nét mặt toát lên vẻ đôn hậu.", "Tính từ Hán Việt hai tiếng, thường khen các cụ già.", "Tiếng đầu là “phúc”."], a: "phúc hậu", acc: ["đôn hậu"], why: "Người phúc hậu được mọi người quý mến." },
  { id: "R2-336", lv: 3, tp: "vocab", h: ["Nghèo mà trong sạch, giữ được phẩm giá.", "Tính từ Hán Việt hai tiếng.", "Tiếng đầu là “thanh”."], a: "thanh bạch", why: "Nguyễn Trãi, Chu Văn An sống thanh bạch." },
  { id: "R2-337", lv: 3, tp: "vocab", h: ["Bữa ăn đơn giản, ít món, ít dầu mỡ.", "Tính từ Hán Việt hai tiếng.", "Tiếng đầu là “thanh”."], a: "thanh đạm", why: "Bữa cơm thanh đạm nhưng ấm cúng." },
  { id: "R2-338", lv: 3, tp: "vocab", h: ["Chi tiêu dè sẻn từng đồng vì cuộc sống khó khăn.", "Từ láy hai tiếng.", "Tiếng đầu là “tằn”."], a: "tằn tiện", acc: ["chắt bóp"], why: "Tằn tiện là tiết kiệm tối đa." },
  { id: "R2-339", lv: 3, tp: "vocab", fam: "haophong", h: ["Hà tiện đến mức quá đáng, không dám chi tiêu cho ai.", "Từ hai tiếng, gần nghĩa với “bủn xỉn”.", "Tiếng đầu là “keo”."], a: "keo kiệt", acc: ["bủn xỉn", "hà tiện"], why: "Keo kiệt bị chê là “vắt cổ chày ra nước”." },
  { id: "R2-340", lv: 3, tp: "vocab", h: ["Sang trọng, tốn kém quá mức cần thiết.", "Tính từ Hán Việt hai tiếng.", "Tiếng đầu là “xa”."], a: "xa hoa", acc: ["xa xỉ"], why: "Lối sống xa hoa dễ dẫn tới lãng phí." },
  { id: "R2-341", lv: 3, tp: "vocab", h: ["Hão huyền, chuộng vẻ hào nhoáng bên ngoài mà rỗng tuếch bên trong.", "Tính từ Hán Việt hai tiếng.", "Tiếng đầu là “phù”."], a: "phù phiếm", why: "“Phù” là nổi, “phiếm” là trôi — không thực chất." },
  { id: "R2-342", lv: 3, tp: "vocab", h: ["Nói khéo, khen bợ đỡ người trên để cầu lợi.", "Động từ Hán Việt hai tiếng.", "Tiếng đầu là “xu”."], a: "xu nịnh", acc: ["nịnh hót", "nịnh bợ"], why: "Xu nịnh là thói xấu cần tránh." },
  { id: "R2-343", lv: 3, tp: "vocab", h: ["Hùa theo người khác một cách mù quáng, không suy nghĩ.", "Động từ hai tiếng.", "Tiếng đầu là “a”."], a: "a dua", acc: ["ba phải"], why: "A dua là “gió chiều nào che chiều ấy”." },
  { id: "R2-344", lv: 3, tp: "vocab", h: ["Nói phóng đại, khoe khoang những điều không có thật.", "Động từ hai tiếng.", "Tiếng đầu là “khoác”."], a: "khoác lác", acc: ["ba hoa", "nói khoác"], why: "Khoác lác là nói quá sự thật để khoe." },
  { id: "R2-345", lv: 3, tp: "vocab", fam: "canthan", h: ["Làm ẩu, qua loa, thiếu cẩn thận.", "Tính từ Hán Việt hai tiếng.", "Tiếng đầu là “cẩu”."], a: "cẩu thả", acc: ["ẩu", "qua loa"], why: "Cẩu thả là trái với cẩn thận." },
  { id: "R2-346", lv: 3, tp: "vocab", h: ["Vội vàng, thiếu suy nghĩ, hành động thiếu bình tĩnh.", "Từ láy hai tiếng.", "Tiếng đầu là “hấp”."], a: "hấp tấp", acc: ["vội vàng", "bộp chộp"], why: "Hấp tấp dễ làm hỏng việc." },
  { id: "R2-347", lv: 3, tp: "vocab", h: ["Ngại làm mất lòng nên không dám từ chối ai điều gì.", "Tính từ hai tiếng.", "Tiếng đầu là “cả”."], a: "cả nể", why: "Cả nể quá dễ bị người khác lợi dụng." },
  { id: "R2-348", lv: 3, tp: "vocab", h: ["Yếu đuối, thiếu cứng rắn, không dám quyết định.", "Tính từ Hán Việt hai tiếng.", "Tiếng đầu là “nhu”."], a: "nhu nhược", why: "Nhu nhược: “nhu” là mềm, “nhược” là yếu." },
  { id: "R2-349", lv: 3, tp: "vocab", h: ["Khư khư giữ ý mình, không chịu nghe ai, không chịu thay đổi.", "Tính từ Hán Việt hai tiếng.", "Tiếng đầu là “cố”."], a: "cố chấp", acc: ["bảo thủ"], why: "Người cố chấp khó tiếp thu cái mới." },
  { id: "R2-350", lv: 3, tp: "vocab", h: ["Sâu sắc, có ý nghĩa sâu xa, cần ngẫm mới hiểu hết.", "Tính từ Hán Việt hai tiếng, thường khen lời nói, câu văn.", "Tiếng đầu là “thâm”."], a: "thâm thuý", acc: ["thâm thúy", "sâu sắc"], why: "Tục ngữ ngắn gọn mà thâm thuý." },
  { id: "R2-351", lv: 3, tp: "vocab", h: ["Biết rõ ràng, cặn kẽ từng chi tiết.", "Tính từ Hán Việt hai tiếng.", "Tiếng đầu là “tường”."], a: "tường tận", acc: ["cặn kẽ", "thấu đáo"], why: "“Tường” là rõ, “tận” là hết." },
  { id: "R2-352", lv: 3, tp: "vocab", h: ["Có đạo đức tốt, được người khác kính phục.", "Tính từ hai tiếng.", "Tiếng đầu là “đức”."], a: "đức độ", why: "Người đức độ được cảm phục bằng cả tấm lòng." },
  { id: "R2-353", lv: 3, tp: "vocab", h: ["Sống ở nơi xa quê hương, xứ người.", "Tính từ Hán Việt hai tiếng.", "Tiếng đầu là “tha”."], a: "tha hương", acc: ["xa xứ", "ly hương", "li hương"], why: "“Tha” là khác, “hương” là làng: quê người." },
  { id: "R2-354", lv: 3, tp: "vocab", h: ["Trôi dạt nay đây mai đó, không chốn dừng chân.", "Động từ Hán Việt hai tiếng.", "Tiếng đầu là “phiêu”."], a: "phiêu bạt", acc: ["lưu lạc", "phiêu dạt", "trôi dạt"], why: "Phiêu bạt là lang thang khắp nơi." },
  { id: "R2-355", lv: 3, tp: "vocab", h: ["Vất vả, nhọc nhằn và nghèo khổ.", "Tính từ hai tiếng.", "Tiếng đầu là “cơ”."], a: "cơ cực", acc: ["khổ cực", "cực khổ"], why: "Cơ cực là khổ sở về vật chất lẫn tinh thần." },
  { id: "R2-356", lv: 3, tp: "vocab", h: ["Vất vả làm lụng ngoài đồng, quần áo lấm lem, giản dị.", "Từ láy hai tiếng.", "Tiếng đầu là “lam”."], a: "lam lũ", why: "Lam lũ thường tả người nông dân vất vả." },
  { id: "R2-357", lv: 3, tp: "vocab", h: ["Chịu thương chịu khó, buôn bán làm lụng vất vả để lo cho gia đình.", "Thường dùng để khen người mẹ, người vợ.", "Tiếng đầu là “tần”."], a: "tần tảo", acc: ["chịu thương chịu khó"], why: "Tần tảo gợi hình ảnh người phụ nữ Việt đảm đang." },
  { id: "R2-358", lv: 3, tp: "vocab", h: ["Vắng vẻ, lạnh lẽo, buồn bã, không một bóng người.", "Từ hai tiếng.", "Tiếng đầu là “hiu”."], a: "hiu quạnh", acc: ["quạnh hiu"], why: "Hiu quạnh gợi nỗi cô đơn." },
  { id: "R2-359", lv: 3, tp: "vocab", h: ["Hoang vắng, chưa có dấu chân con người khai phá.", "Tính từ hai tiếng.", "Tiếng đầu là “hoang”."], a: "hoang vu", acc: ["hoang sơ", "hoang vắng"], why: "Vùng đất hoang vu chưa ai đặt chân tới." },
  { id: "R2-360", lv: 3, tp: "vocab", h: ["To lớn, đẹp đẽ và lộng lẫy, thường tả cung điện, lâu đài.", "Tính từ hai tiếng.", "Tiếng đầu là “nguy”."], a: "nguy nga", acc: ["tráng lệ"], why: "Cung điện nguy nga tráng lệ." },
  { id: "R2-361", lv: 3, tp: "vocab", h: ["Mang vẻ đẹp xưa cũ, có từ lâu đời.", "Tính từ Hán Việt hai tiếng, hay dùng tả phố Hội An.", "Tiếng đầu là “cổ”."], a: "cổ kính", why: "Phố cổ Hội An mang vẻ cổ kính." },
  { id: "R2-362", lv: 3, tp: "vocab", h: ["Phủ đầy rêu, mang dấu vết thời gian lâu năm.", "Thường tả mái chùa, bức tường cũ.", "Tiếng đầu là “rêu”."], a: "rêu phong", why: "Mái ngói rêu phong gợi vẻ trầm mặc." },
  { id: "R2-363", lv: 3, tp: "vocab", h: ["Có vẻ đẹp nên thơ, gợi cảm xúc lãng mạn.", "Tính từ hai tiếng, Đà Lạt hay được gọi là thành phố …", "Tiếng đầu là “thơ”."], a: "thơ mộng", acc: ["mộng mơ", "nên thơ"], why: "Cảnh thơ mộng khiến lòng người say đắm." },
  { id: "R2-364", lv: 3, tp: "vocab", h: ["Dáng đi mềm mại, uyển chuyển, duyên dáng của người con gái.", "Từ hai tiếng, thường đi với “thướt tha”.", "Tiếng đầu là “yểu”."], a: "yểu điệu", why: "“Yểu điệu thục nữ” là người con gái nết na, duyên dáng." },
  { id: "R2-365", lv: 3, tp: "vocab", h: ["Hiền dịu, nết na, nhẹ nhàng trong cử chỉ, lời nói.", "Tính từ hai tiếng, thường khen con gái.", "Tiếng đầu là “thuỳ”."], a: "thuỳ mị", acc: ["thùy mị", "nết na"], why: "Thuỳ mị là dịu dàng, nết na." },
  { id: "R2-366", lv: 3, tp: "vocab", fam: "kieu", h: ["Đứng đắn, nghiêm trang và đẹp một cách giản dị.", "Nguyễn Du dùng từ này tả Thuý Vân: “Hoa cười ngọc thốt …”.", "Tiếng đầu là “đoan”."], a: "đoan trang", why: "Đoan trang là đẹp nết, đẹp người, đứng đắn." },
  { id: "R2-367", lv: 3, tp: "vocab", h: ["Sáng sủa, thông minh lộ rõ trên khuôn mặt (thường tả con trai).", "Tính từ hai tiếng.", "Tiếng đầu là “khôi”."], a: "khôi ngô", acc: ["tuấn tú", "khôi ngô tuấn tú"], why: "“Khôi ngô tuấn tú” là khen người con trai đẹp, sáng sủa." },
  { id: "R2-368", lv: 3, tp: "vocab", h: ["Thân hình to lớn, chắc khoẻ, cơ bắp nở nang.", "Tính từ hai tiếng.", "Tiếng đầu là “vạm”."], a: "vạm vỡ", acc: ["lực lưỡng", "cường tráng"], why: "Vạm vỡ tả người khoẻ mạnh, to lớn." },
  { id: "R2-369", lv: 3, tp: "vocab", h: ["Gầy rạc, xanh xao, sa sút hẳn đi vì ốm hoặc vất vả.", "Tính từ Hán Việt hai tiếng.", "Tiếng đầu là “tiều”."], a: "tiều tuỵ", acc: ["tiều tụy", "hốc hác"], why: "Tiều tuỵ tả dáng vẻ mệt mỏi, suy kiệt." },
  { id: "R2-370", lv: 3, tp: "vocab", h: ["Ngẩn ngơ, như người mất hồn, không tập trung được.", "Từ láy hai tiếng.", "Tiếng đầu là “bần”."], a: "bần thần", acc: ["thẫn thờ", "ngẩn ngơ"], why: "Bần thần là uể oải, ngơ ngẩn." },
  { id: "R2-371", lv: 3, tp: "lit", h: ["Văn bản vua ban ra để công bố mệnh lệnh cho thần dân.", "Lý Công Uẩn viết “… dời đô” năm 1010.", "Một tiếng, bắt đầu bằng “ch”."], a: "chiếu", acc: ["chiếu thư"], why: "“Chiếu dời đô” (Thiên đô chiếu) của Lý Thái Tổ." },
  { id: "R2-372", lv: 3, tp: "lit", h: ["Bài văn đọc trong lễ cúng để tưởng nhớ người đã mất.", "Nguyễn Đình Chiểu có bài nổi tiếng về nghĩa sĩ Cần Giuộc.", "Tiếng đầu là “văn”."], a: "văn tế", why: "“Văn tế nghĩa sĩ Cần Giuộc” là áng văn tế bất hủ." },
  { id: "R2-373", lv: 3, tp: "lit", h: ["Tên khác mà nhà văn, nhà thơ dùng để ký tác phẩm thay tên thật.", "“Tô Hoài”, “Nam Cao” đều là ví dụ.", "Tiếng đầu là “bút”."], a: "bút danh", why: "Bút danh có thể gợi quê hương hay một kỷ niệm." },
  { id: "R2-374", lv: 3, tp: "lit", h: ["Chuỗi sự việc được sắp xếp theo trình tự, tạo nên câu chuyện.", "Danh từ hai tiếng.", "Tiếng đầu là “cốt”."], a: "cốt truyện", why: "Cốt truyện là xương sống của tác phẩm tự sự." },
  { id: "R2-375", lv: 3, tp: "lit", h: ["Tác phẩm thơ rất dài, có quy mô lớn, nhiều chương.", "“Mặt đường khát vọng” là một ví dụ.", "Tiếng đầu là “trường”."], a: "trường ca", why: "Trường ca thường viết về những đề tài lớn lao." },
  { id: "R2-376", lv: 3, tp: "lit", h: ["Thể văn ghi lại cảm xúc, suy nghĩ một cách tự do, phóng túng.", "“Người lái đò Sông Đà” của Nguyễn Tuân thuộc thể này.", "Tiếng đầu là “tuỳ”."], a: "tuỳ bút", acc: ["tùy bút"], why: "“Tuỳ bút” là theo ngọn bút mà viết." },
  { id: "R2-377", lv: 3, tp: "lit", h: ["Tác phẩm kể lại những sự việc có thật mà tác giả đã trải qua.", "“Những ngày thơ ấu” của Nguyên Hồng thuộc thể này.", "Tiếng đầu là “hồi”."], a: "hồi ký", acc: ["hồi kí"], why: "Hồi ký là ghi lại theo trí nhớ." },
  { id: "R2-378", lv: 3, tp: "lit", h: ["Tác phẩm văn xuôi dài, nhiều nhân vật, nhiều tình tiết.", "“Tắt đèn”, “Số đỏ” thuộc thể loại này.", "Tiếng đầu là “tiểu”."], a: "tiểu thuyết", why: "Tiểu thuyết phản ánh đời sống rộng lớn." },
  { id: "R2-379", lv: 3, tp: "lit", h: ["Câu chuyện, sự tích xưa được dẫn trong thơ văn để nói ý mình.", "“Bá Nha – Tử Kỳ” là một ví dụ.", "Tiếng đầu là “điển”."], a: "điển tích", acc: ["điển cố"], why: "Văn học trung đại dùng nhiều điển tích." },
  { id: "R2-380", lv: 3, tp: "vocab", h: ["Bộ bốn bức tranh treo cùng nhau, thường vẽ cảnh xuân, hạ, thu, đông.", "Hay vẽ bốn loài cây: mai, lan, cúc, trúc.", "Gồm ba tiếng, tiếng đầu là “tranh”."], a: "tranh tứ bình", acc: ["tứ bình"], why: "“Tứ” là bốn, “bình” là tấm." },
  { id: "R2-381", lv: 3, tp: "lit", h: ["Nhóm câu thơ tách riêng, thường bốn câu, giống một đoạn văn trong bài thơ.", "Danh từ hai tiếng.", "Tiếng đầu là “khổ”."], a: "khổ thơ", why: "Bài thơ thường được chia thành nhiều khổ." },
  { id: "R2-382", lv: 3, tp: "lit", h: ["Tác phẩm viết để diễn trên sân khấu, chủ yếu bằng lời thoại.", "“Vũ Như Tô” của Nguyễn Huy Tưởng thuộc thể loại này.", "Một tiếng, bắt đầu bằng “k”."], a: "kịch", acc: ["kịch nói", "vở kịch"], why: "Kịch được thể hiện qua lời thoại và hành động." },
  { id: "R2-383", lv: 3, tp: "vocab", h: ["Tình trạng nước biển, nước sông xâm nhập vào đồng ruộng làm cây trồng chết.", "Đồng bằng sông Cửu Long chịu ảnh hưởng nặng mùa khô.", "Gồm ba tiếng, tiếng đầu là “xâm”."], a: "xâm nhập mặn", acc: ["nhiễm mặn"], why: "Xâm nhập mặn gây thiệt hại lớn cho nông nghiệp." },
  { id: "R2-384", lv: 3, tp: "vocab", h: ["Hiện tượng Trái Đất nóng dần lên vì khí thải.", "Danh từ ba tiếng.", "Tiếng đầu là “hiệu”."], a: "hiệu ứng nhà kính", acc: ["nóng lên toàn cầu"], why: "Khí CO₂ giữ nhiệt như mái kính nhà trồng cây." },
  { id: "R2-385", lv: 3, tp: "vocab", h: ["Nguồn năng lượng lấy từ ánh nắng mặt trời, gió, nước, không bao giờ cạn.", "Danh từ ba tiếng.", "Tiếng đầu là “năng”."], a: "năng lượng tái tạo", acc: ["năng lượng sạch"], why: "Năng lượng tái tạo thân thiện với môi trường." },
  { id: "R2-386", lv: 3, tp: "vocab", h: ["Loài sắp bị tuyệt chủng, được ghi tên vào một cuốn sách để bảo vệ.", "Danh từ hai tiếng, gắn với màu của cuốn sách.", "Tiếng đầu là “sách”."], a: "sách đỏ", why: "Sách Đỏ ghi danh các loài động, thực vật quý hiếm." },
  { id: "R2-387", lv: 3, tp: "vocab", h: ["Một loài không còn cá thể nào tồn tại trên Trái Đất.", "Khủng long đã rơi vào tình trạng này.", "Tiếng đầu là “tuyệt”."], a: "tuyệt chủng", why: "“Tuyệt” là dứt, “chủng” là giống loài." },
  { id: "R2-388", lv: 3, tp: "vocab", h: ["Khu rừng được nhà nước bảo vệ, cấm chặt phá, săn bắt.", "Cúc Phương là nơi đầu tiên ở Việt Nam.", "Tiếng đầu là “vườn”."], a: "vườn quốc gia", acc: ["khu bảo tồn"], why: "Vườn quốc gia Cúc Phương thành lập năm 1962." },
  { id: "R2-389", lv: 3, tp: "vocab", h: ["Quan hệ giao thương mua bán hàng hoá giữa các nước.", "Danh từ Hán Việt hai tiếng.", "Tiếng đầu là “ngoại”."], a: "ngoại thương", why: "“Ngoại” là bên ngoài, “thương” là buôn bán." },
  { id: "R2-390", lv: 3, tp: "vocab", h: ["Người đại diện cho một nước ở nước khác.", "Ông Mạc Đĩnh Chi từng đi sứ, làm công việc này thời xưa.", "Tiếng đầu là “đại”."], a: "đại sứ", acc: ["sứ thần", "sứ giả"], why: "Đại sứ thời nay; sứ thần, sứ giả thời xưa." },
  { id: "R2-391", lv: 3, tp: "vocab", h: ["Nơi vua ở và làm việc, có tường thành bao quanh.", "Huế, Thăng Long đều có.", "Tiếng đầu là “hoàng”."], a: "hoàng thành", acc: ["kinh thành", "cung điện"], why: "Hoàng thành Thăng Long là di sản thế giới." },
  { id: "R2-392", lv: 3, tp: "vocab", h: ["Toàn bộ những người cùng sinh ra trong một khoảng thời gian, cùng lứa tuổi.", "Danh từ Hán Việt hai tiếng.", "Tiếng đầu là “thế”."], a: "thế hệ", why: "Thế hệ trẻ là chủ nhân tương lai." },
  { id: "R2-393", lv: 3, tp: "vocab", h: ["Ra sức làm việc hết mình, không tiếc công sức.", "Từ Hán Việt hai tiếng, gần nghĩa với “dốc sức”.", "Tiếng đầu là “tận”."], a: "tận lực", acc: ["dốc sức", "hết sức", "dốc lòng"], why: "Tận lực là dùng hết sức." },
  { id: "R2-394", lv: 3, tp: "vocab", h: ["Thông thạo, giỏi giang trong nghề nghiệp nhờ làm lâu.", "Tính từ Hán Việt hai tiếng.", "Tiếng đầu là “thành”."], a: "thành thạo", acc: ["thuần thục", "lành nghề"], why: "Thành thạo là nắm vững và làm giỏi." },
  { id: "R2-395", lv: 3, tp: "vocab", h: ["Rút ra bài học từ những việc đã qua.", "Động từ cụm hai tiếng, gần nghĩa với “tổng kết”.", "Tiếng đầu là “đúc”."], a: "đúc kết", acc: ["đúc rút"], why: "Tục ngữ đúc kết kinh nghiệm của nhân dân." },
  { id: "R2-396", lv: 3, tp: "vocab", h: ["Bỗng hiểu ra điều mà trước đó mình chưa hiểu, chưa biết.", "Động từ hai tiếng, gần nghĩa với “ngộ ra”.", "Tiếng đầu là “vỡ”."], a: "vỡ lẽ", acc: ["ngộ ra", "hiểu ra"], why: "Vỡ lẽ là chợt hiểu ra sự thật." },
  { id: "R2-397", lv: 3, tp: "vocab", h: ["Làm cho người khác thấy rõ một điều bằng chứng cứ, lý lẽ.", "Động từ Hán Việt hai tiếng.", "Tiếng đầu là “chứng”."], a: "chứng minh", why: "Bài văn nghị luận cần chứng minh luận điểm." },
  { id: "R2-398", lv: 3, tp: "vocab", h: ["Ý kiến chính, quan điểm lớn trong bài văn nghị luận.", "Danh từ Hán Việt hai tiếng.", "Tiếng đầu là “luận”."], a: "luận điểm", why: "Mỗi luận điểm cần lý lẽ và dẫn chứng." },
  { id: "R2-399", lv: 3, tp: "vocab", h: ["Ví dụ, sự việc có thật được đưa ra làm bằng chứng.", "Danh từ Hán Việt hai tiếng.", "Tiếng đầu là “dẫn”."], a: "dẫn chứng", why: "Dẫn chứng làm lý lẽ thêm thuyết phục." },
  { id: "R2-400", lv: 3, tp: "vocab", h: ["Sự thấu hiểu, đặt mình vào hoàn cảnh người khác để chia sẻ.", "Danh từ Hán Việt hai tiếng.", "Tiếng đầu là “đồng”."], a: "đồng cảm", acc: ["cảm thông", "thông cảm"], why: "Đồng cảm giúp gắn kết con người." },
  { id: "R2-401", lv: 3, tp: "vocab", h: ["Không theo khuôn mẫu cũ, có cái mới lạ, độc đáo.", "Tính từ Hán Việt hai tiếng, gần nghĩa với “đổi mới”.", "Tiếng đầu là “sáng”."], a: "sáng tạo", why: "Sáng tạo là tạo ra cái mới." },
  { id: "R2-402", lv: 3, tp: "vocab", h: ["Có giá trị riêng, không giống ai, không lẫn với cái khác.", "Tính từ Hán Việt hai tiếng.", "Tiếng đầu là “độc”."], a: "độc đáo", why: "Độc đáo là có một không hai." },
  { id: "R2-403", lv: 3, tp: "vocab", fam: "kieu", h: ["Thuộc về đời sống bên trong như tư tưởng, tình cảm, ý chí — không sờ thấy được.", "Trái nghĩa với “vật chất”.", "Tiếng đầu là “tinh”."], a: "tinh thần", why: "Đời sống tinh thần quan trọng như vật chất." },
  { id: "R2-404", lv: 3, tp: "vocab", fam: "doclap", h: ["Trạng thái hoàn toàn tự do của một dân tộc, không lệ thuộc nước khác.", "“Không có gì quý hơn … tự do.”", "Tiếng đầu là “độc”."], a: "độc lập", why: "Câu nói nổi tiếng của Chủ tịch Hồ Chí Minh năm 1966." },
  { id: "R2-405", lv: 3, tp: "vocab", h: ["Toàn bộ lãnh thổ, vùng trời, vùng biển thuộc quyền của một quốc gia.", "Danh từ Hán Việt hai tiếng.", "Tiếng đầu là “chủ”."], a: "chủ quyền", why: "Bảo vệ chủ quyền biển đảo là trách nhiệm của mọi người." },
  { id: "R2-406", lv: 3, tp: "vocab", h: ["Sự bình yên, không có chiến tranh.", "Chim bồ câu trắng là biểu tượng.", "Tiếng đầu là “hoà”."], a: "hoà bình", acc: ["hòa bình"], why: "Hoà bình là khát vọng của mọi dân tộc." },
  { id: "R2-407", lv: 3, tp: "vocab", h: ["Học hành chăm chỉ, cần cù trong thời gian dài, như “dùi mài kinh sử”.", "Từ ghép hai tiếng.", "Tiếng đầu là “miệt”."], a: "miệt mài", why: "Miệt mài là say sưa, không biết mệt." },
];

export const CLUES_MORE: Clue[] = [...EASY, ...MEDIUM, ...HARD];
